window.__LIBQ=window.__LIBQ||{};window.__LIBQ["pham-nhan-tu-tien"]=window.__LIBQ["pham-nhan-tu-tien"]||{};window.__LIBQ["pham-nhan-tu-tien"]["q08"]=window.__LIBQ["pham-nhan-tu-tien"]["q08"]||{};window.__LIBQ["pham-nhan-tu-tien"]["q08"]["factions"]={"updatedAt":"2026-07-26","count":66,"factions":[{"id":"thien-dong-thuong-hao","name":"Thiên Đông Thương Hào","cn":"","aliases":["Thiên Đông Thương Hành","Thiên Đông hiệu buôn"],"type":"thuong-hao","typeLabel":"Thương hào","diaBan":"Thanh La Sa Mạc","nhanVatChinh":["Trương Khuê","Tiểu Thất","Thanh niên cầm Viên Bàn","Các kỵ sĩ cưỡi thanh sắc cự lang","Hàn Lập","Phương phu nhân"],"blurb":"Thương hào có đội kỵ sĩ hoạt động trong Thanh La Sa Mạc. Tổ chức đề nghị cứu Hàn Lập và đưa hắn rời sa mạc để đổi lấy hai mươi năm phục vụ.","detail":"Đội kỵ sĩ của Thiên Đông Thương Hào phát hiện Hàn Lập tại vùng sâu Thanh La Sa Mạc. Trương Khuê thay mặt tổ chức đưa ra giao kèo hai mươi năm và chuẩn bị dùng Huyết Chú Văn Thư để ràng buộc thỏa thuận.","quyMo":"Có đội kỵ sĩ hoạt động tại Thanh La Sa Mạc","quanHe":"Thu nhận Hàn Lập bằng giao kèo phục vụ hai mươi năm.","trangThai":"Đang chuẩn bị ứng phó thú triều","capNhatToi":"@c1263","thanhVien":[{"ten":"Trương Khuê","chucVu":"Đội trưởng hộ vệ","tuChuong":"@c1263","trangThai":"Đang phục vụ"},{"ten":"Tiểu Thất","chucVu":"Kỵ sĩ","tuChuong":"@c1263","trangThai":"Đang hoạt động"},{"ten":"Thanh niên cầm Viên Bàn","chucVu":"Thành viên đội kỵ sĩ","tuChuong":"@c1263","trangThai":"Đang hoạt động"},{"ten":"Các kỵ sĩ cưỡi thanh sắc cự lang","chucVu":"Đội kỵ sĩ","tuChuong":"@c1263","trangThai":"Đang hoạt động"},{"ten":"Hàn Lập","chucVu":"Phó đội hộ vệ","tuChuong":"@c1263","trangThai":"Đang phục vụ"},{"ten":"Phương phu nhân","chucVu":"Người chủ trì tại Tây viện","tuChuong":"@c1273","trangThai":"Đang hoạt động"}],"tabs":{"tienTrinh":[{"chuong":"@c1263","loai":"mở rộng/mất địa bàn","importance":"normal","giaiDoan":"Thu nhận Hàn Lập","text":"Thiên Đông Thương Hào đề nghị đưa Hàn Lập khỏi Thanh La Sa Mạc để đổi lấy hai mươi năm phục vụ.","anchor":"Ngươi phải làm việc cho bổn hiệu buôn chúng ta trong vòng hai mươi năm.","trangThaiMoc":"Đang thu nhận Hàn Lập"},{"chuong":"@c1273","loai":"nhắc tới","importance":"normal","giaiDoan":"Bao trọn Tây viện","text":"Thiên Đông Thương Hào có số người đông nên bao trọn Tây viện của Như Vân Khách Điếm làm nơi lưu trú.","anchor":"Các vị đại gia Thiên Đông Thương Hành bởi vì nhân số quá nhiều, đã bao cả khu Tây viện."},{"chuong":"@c1275","loai":"nhắc tới","importance":"normal","giaiDoan":"Chuẩn bị chống thú triều","text":"Thiên Đông Thương Hào bổ nhiệm Hàn Lập làm phó đội hộ vệ và duy trì đội ngũ tại An Viễn Thành trong lúc thú triều kéo tới.","anchor":"sau khi rời khỏi tiểu viện liền đi theo đám người hán tử mặt thẹo"}]},"nguon":["@c1263","@c1273","@c1275"]},{"id":"huyet-chu-mon","name":"Huyết Chú Môn","cn":"","aliases":[],"type":"tong-mon","typeLabel":"Môn phái","diaBan":"Không rõ","nhanVatChinh":[],"blurb":"Môn phái độc quyền luyện chế Huyết Chú Văn Thư, loại khế ước dùng huyết chú để ràng buộc người tự nguyện ký kết.","detail":"Trương Khuê xác nhận Huyết Chú Văn Thư là vật do Huyết Chú Môn độc môn luyện chế.","tranPhai":"Huyết Chú Văn Thư","trangThai":"Đang tồn tại","capNhatToi":"@c1263","tabs":{"tienTrinh":[{"chuong":"@c1263","loai":"nhắc tới","importance":"bridge","giaiDoan":"Nguồn gốc văn thư","text":"Huyết Chú Môn được xác nhận là môn phái độc quyền luyện chế Huyết Chú Văn Thư.","anchor":"đây là độc môn do Huyết chú môn luyện chế thành","trangThaiMoc":"Đang tồn tại"}]},"nguon":["@c1263"]},{"id":"phu-gia","name":"Phù gia","cn":"","aliases":[],"type":"gia-toc","typeLabel":"Gia tộc","diaBan":"Không rõ","nhanVatChinh":["Phù lão"],"blurb":"Gia tộc truyền thừa Huyền Thiên Kim Châm thuật, trong đó Phù lão là một đệ tử.","detail":"Phù gia lưu truyền kim châm thuật có khả năng hỗ trợ người bị tổn thương kinh mạch. Phù lão tự nhận chỉ là một đệ tử và chỉ nắm được một phần truyền thừa.","tranPhai":"Huyền Thiên Kim Châm thuật","thanhVien":[{"ten":"Phù lão","chucVu":"Đệ tử","tuChuong":"@c1265","trangThai":"Đang thuộc Phù gia"}],"tabs":{"tienTrinh":[{"chuong":"@c1265","loai":"nhắc tới","importance":"normal","giaiDoan":"Hé lộ truyền thừa","text":"Phù gia được hé lộ là gia tộc truyền thừa kim châm thuật mà Phù lão đang sử dụng.","anchor":"Tại hạ chỉ là một tên đệ tử của Phù gia mà thôi","trangThaiMoc":"Đang tồn tại"}]},"capNhatToi":"@c1265","nguon":["@c1265"]},{"id":"cau-lu-son","name":"Cẩu Lũ sơn","cn":"","type":"tong-mon","typeLabel":"Tông môn","diaBan":"Cẩu Lũ sơn","nhanVatChinh":["Nam Kỳ Tử"],"blurb":"Tông môn chuyên tu thần thông khu trùng, có nhiều quy củ hạn chế môn nhân khi đối phó yêu trùng.","detail":"Nam Kỳ Tử và các tu tiên giả đi cùng xa đội xuất thân từ Cẩu Lũ sơn. Nhóm này không trợ chiến nếu đàn Sa Trùng Thú chưa chủ động công kích họ.","nguon":["@c1266"],"tonChi":"Chuyên tu khu trùng thần thông","thanhVien":[{"ten":"Nam Kỳ Tử","chucVu":"Đạo trưởng","tuChuong":"@c1266","trangThai":"đang thuộc"}],"quanHe":"Giữ lập trường không can thiệp khi yêu trùng chưa chủ động công kích môn nhân.","trangThai":"Tồn tại","capNhatToi":"@c1266","tabs":{"tienTrinh":[{"chuong":"@c1266","loai":"nhắc tới","importance":"normal","giaiDoan":"Từ chối trợ chiến","text":"Nhóm tu sĩ Cẩu Lũ sơn từ chối trợ chiến vì đàn Sa Trùng Thú chưa chủ động công kích họ.","anchor":"Đám người đạo trưởng đều xuất thân từ Cẩu Lũ sơn, nếu đám trùng thú không chủ động công kích bọn họ thì họ cũng sẽ không ra tay.","trangThaiMoc":"Không can thiệp"}]}},{"id":"quy-xa-doi","name":"Quy xa đội","cn":"","type":"doi-ngu","typeLabel":"Đội ngũ hộ tống","diaBan":"Sa mạc hoang vu thuộc Linh Giới","nhanVatChinh":["Trương Khuê","Hương nhi","Thúy sam thiếu nữ","Thiếu nữ hồng sam ít tuổi nhất"],"blurb":"Đội ngũ vận chuyển gồm hơn ba mươi cự quy và khoảng sáu bảy mươi kỵ sĩ cưỡi cự lang. Đội bị hàng trăm Sa Trùng Thú vây công và chịu hơn hai mươi trường hợp chết hoặc bị thương.","detail":"Khi bụi vàng tiến đến, các cự quy phủ phục và rút đầu cùng tứ chi vào mai để tạo tuyến chắn. Các kỵ sĩ tập hợp dưới sự chỉ huy của Trương Khuê, còn ba thiếu nữ triển khai Tiểu Hồi Xuân Trận khi phòng tuyến bị xuyên thủng.","lanhDaoHienThoi":"Trương Khuê","quyMo":"Hơn ba mươi cự quy và khoảng sáu bảy mươi kỵ sĩ cưỡi cự lang","trangThai":"Đang bị Sa Trùng Thú vây công","thanhVien":[{"ten":"Trương Khuê","chucVu":"Thủ lĩnh kỵ sĩ","tuChuong":"@c1267","trangThai":"đang hoạt động"},{"ten":"Hương nhi","chucVu":"Người bố trí trận pháp","tuChuong":"@c1267","trangThai":"đang hoạt động"},{"ten":"Thúy sam thiếu nữ","chucVu":"Người bố trí trận pháp","tuChuong":"@c1267","trangThai":"đang hoạt động"},{"ten":"Thiếu nữ hồng sam ít tuổi nhất","chucVu":"Người bố trí trận pháp","tuChuong":"@c1267","trangThai":"đang hoạt động"}],"capNhatToi":"@c1267","tabs":{"tienTrinh":[{"chuong":"@c1267","loai":"khai chiến","importance":"normal","giaiDoan":"Bị Sa Trùng Thú vây công","text":"Quy xa đội dựng tuyến phòng ngự bằng cự quy nhưng vẫn bị Sa Trùng Thú xuyên thủng, khiến hơn hai mươi thủ vệ chết hoặc bị thương trước khi Tiểu Hồi Xuân Trận được triển khai.","trangThaiMoc":"Phòng tuyến tạm thời giành lại ưu thế","anchor":"Lúc này có khoảng hơn hai mươi tên thủ vệ bị chết hoặc bị thương dưới tay của mấy con cự trùng này."}]},"nguon":["@c1267"]},{"id":"huong-lau-son","name":"Hưởng Lâu Sơn","cn":"","type":"tong-mon","typeLabel":"Tông môn tu tiên","diaBan":"Chưa rõ","nhanVatChinh":["Nam Kỳ Tử"],"blurb":"Thế lực tu tiên có Nam Kỳ Tử cùng các đồng môn được Phương phu nhân thuê bảo vệ đoàn xe của Thiên Đông Thương Hào.","detail":"Nhóm tu sĩ Hưởng Lâu Sơn hoàn thành nhiệm vụ khi hàng hóa được đưa an toàn vào An Viễn Thành, sau đó rời khỏi đoàn.","thanhVien":[{"ten":"Nam Kỳ Tử","chucVu":"Tu sĩ hộ tống","tuChuong":"@c1270","trangThai":"Đã hoàn thành nhiệm vụ"}],"trangThai":"Đang hoạt động","capNhatToi":"@c1270","tabs":{"tienTrinh":[{"chuong":"@c1270","loai":"nhắc tới","importance":"normal","giaiDoan":"Hoàn thành nhiệm vụ hộ tống","text":"Các tu sĩ Hưởng Lâu Sơn rời đoàn sau khi hàng hóa được giao an toàn.","anchor":"Kết quả vài tên hưởng lâu sơn tu sĩ cũng rời mọi người, bỏ đi","trangThaiMoc":"Hoàn thành nhiệm vụ hộ tống"}]},"nguon":["@c1270"]},{"id":"tam-hoang","name":"Tam Hoàng","cn":"","type":"lien-minh","typeLabel":"Thế lực","diaBan":"Linh Giới","nhanVatChinh":[],"blurb":"Một bên tham gia hiệp nghị với Thất Yêu Vương về giới hạn lực lượng trong thú triều. Theo hiệp nghị, tu sĩ Kết Đan không được trợ giúp các thành lớn chống lại thú triều.","detail":"Tam Hoàng cùng Thất Yêu Vương thiết lập giới hạn can thiệp vào các đợt thú triều. Phía nhân tộc không được điều động tu sĩ Kết Đan trợ giúp các thành lớn, khiến luyện thể sĩ trở thành lực lượng phòng thủ quan trọng.","quanHe":"Có hiệp nghị hạn chế lực lượng tham chiến với Thất Yêu Vương.","trangThai":"Hiệp nghị đang có hiệu lực","capNhatToi":"@c1271","tabs":{"tienTrinh":[{"chuong":"@c1271","loai":"nhắc tới","importance":"normal","giaiDoan":"Hé lộ hiệp nghị thú triều","text":"Hiệp nghị của Tam Hoàng với Thất Yêu Vương cấm tu sĩ Kết Đan trợ giúp các thành lớn chống thú triều.","anchor":"căn cứ Tam Hoàng cùng Thất Yêu Vương hiệp nghị","trangThaiMoc":"Hiệp nghị đang có hiệu lực"}]},"nguon":["@c1271"]},{"id":"that-yeu-vuong","name":"Thất Yêu Vương","cn":"","type":"lien-minh","typeLabel":"Thế lực yêu tộc","diaBan":"Linh Giới","nhanVatChinh":[],"blurb":"Phía yêu tộc tham gia hiệp nghị với Tam Hoàng về giới hạn lực lượng trong thú triều. Đổi lại việc tu sĩ Kết Đan không can thiệp, yêu thú cao hơn cấp năm cũng không được xuất hiện.","detail":"Thất Yêu Vương là bên đối ứng với Tam Hoàng trong hiệp nghị điều chỉnh thú triều. Hiệp nghị ngăn yêu thú cao giai ngoài cấp năm tham chiến, tạo thế cân bằng với lệnh cấm tu sĩ Kết Đan trợ giúp các thành lớn.","quanHe":"Có hiệp nghị hạn chế lực lượng tham chiến với Tam Hoàng.","trangThai":"Hiệp nghị đang có hiệu lực","capNhatToi":"@c1271","tabs":{"tienTrinh":[{"chuong":"@c1271","loai":"nhắc tới","importance":"normal","giaiDoan":"Hé lộ hiệp nghị thú triều","text":"Theo hiệp nghị với Tam Hoàng, phía Thất Yêu Vương không để yêu thú cao hơn cấp năm xuất hiện trong thú triều.","anchor":"đồng dạng cũng không xuất hiện yêu thú cao giai ngoài ngũ cấp","trangThaiMoc":"Hiệp nghị đang có hiệu lực"}]},"nguon":["@c1271"]},{"id":"nhan-toc-tam-hoang-canh","name":"Nhân tộc Tam Hoàng Cảnh","cn":"","aliases":[],"type":"chủng tộc","typeLabel":"Thế lực nhân tộc","diaBan":"Thiên Nguyên Cảnh, Huyền Vũ Cảnh và Thiên Linh Cảnh","nhanVatChinh":["Thiên Nguyên Thánh Hoàng","Huyền Vũ Phách Hoàng","Thiên Diệu Linh Hoàng"],"blurb":"Khối thế lực nhân tộc tại Linh Giới gồm ba vùng lớn do Tam Hoàng lần lượt thống trị.","detail":"Nhân tộc Tam Hoàng Cảnh cùng Yêu Tộc Thất Yêu Chi Địa duy trì thế cân bằng và dựa vào siêu đại pháp trận chung để bảo vệ lãnh thổ. Hiệp nghị giữa hai tộc hạn chế việc cường giả tùy ý tàn sát quần thể cấp thấp và cấm tu sĩ cao giai tham gia phòng thủ thành thị trong thú triều.","nguonGoc":"","tonChi":"","lanhDaoHienThoi":"Tam Hoàng","capBac":"Ba vùng lãnh thổ","quyMo":"Gồm ba vùng lớn, mỗi vùng có từ hàng trăm đến hơn một nghìn thành thị.","caoThuManhNhat":"Tam Hoàng","soCaoThu":"","tranPhai":"Siêu đại pháp trận bảo hộ Tam Cảnh và Thất Địa","quanHe":"Vừa tranh đấu vừa liên thủ với Yêu Tộc Thất Yêu Chi Địa.","trangThai":"Đang duy trì lãnh thổ và thế cân bằng với Yêu Tộc","thanhVien":[{"ten":"Thiên Nguyên Thánh Hoàng","chucVu":"Người thống trị Thiên Nguyên Cảnh","tuChuong":"@c1272","trangThai":"Đương nhiệm"},{"ten":"Huyền Vũ Phách Hoàng","chucVu":"Người thống trị Huyền Vũ Cảnh","tuChuong":"@c1272","trangThai":"Đương nhiệm"},{"ten":"Thiên Diệu Linh Hoàng","chucVu":"Người thống trị Thiên Linh Cảnh","tuChuong":"@c1272","trangThai":"Đương nhiệm"}],"capNhatToi":"@c1272","nguon":["@c1272"]},{"id":"yeu-toc-that-yeu-chi-dia","name":"Yêu Tộc Thất Yêu Chi Địa","cn":"","aliases":[],"type":"chủng tộc","typeLabel":"Thế lực Yêu Tộc","diaBan":"Thất Yêu Chi Địa","nhanVatChinh":["Thất Yêu Vương"],"blurb":"Khối thế lực Yêu Tộc gồm bảy vùng lãnh thổ do bảy đại Yêu Vương thống trị.","detail":"Yêu Tộc có thực lực tổng thể nhỉnh hơn nhân tộc, trong khi tu sĩ cao giai nhân tộc mạnh hơn đôi chút nên hai bên duy trì thế cân bằng. Yêu Tộc cùng nhân tộc ký hiệp nghị bảo hộ quần thể cấp thấp và cùng dựa vào siêu đại pháp trận che chở lãnh thổ.","nguonGoc":"","tonChi":"","lanhDaoHienThoi":"Thất Yêu Vương","capBac":"Bảy vùng lãnh thổ","quyMo":"Gồm bảy vùng Yêu Tộc.","caoThuManhNhat":"Thất Yêu Vương","soCaoThu":"Bảy Yêu Vương","tranPhai":"Siêu đại pháp trận bảo hộ Tam Cảnh và Thất Địa","quanHe":"Vừa tranh đấu vừa liên thủ với Nhân tộc Tam Hoàng Cảnh.","trangThai":"Đang duy trì lãnh thổ và hiệp nghị với nhân tộc","thanhVien":[{"ten":"Thất Yêu Vương","chucVu":"Những người thống trị Thất Yêu Chi Địa","tuChuong":"@c1272","trangThai":"Đương nhiệm"}],"tabs":{"tienTrinh":[{"chuong":"@c1272","loai":"nhắc tới","importance":"normal","giaiDoan":"Tương quan với nhân tộc","text":"Điển tịch cho biết thực lực tổng thể của Yêu Tộc nhỉnh hơn nhân loại một bậc.","anchor":"Yêu Tộc chỉnh thể thực lực trên nhân loại một bậc"}]},"capNhatToi":"@c1272","nguon":["@c1272"]},{"id":"kim-ngoc-tong","name":"Kim Ngọc Tông","cn":"","type":"tông môn","typeLabel":"Tông môn tu tiên","diaBan":"Có giao tình với cao tầng An Viễn Thành","nhanVatChinh":["Phan Thanh","Nam tử cẩm bào họ Tần","Nam thanh niên đi cùng họ Tần","Nữ thanh niên đi cùng họ Tần"],"blurb":"Tông môn tu tiên có giao tình với cao tầng An Viễn Thành.","detail":"Kim Ngọc Tông phái Phan Thanh cùng ba đồng môn Trúc Cơ tới hỗ trợ An Viễn Thành chống thú triều. Tông môn đồng thời xem cuộc chiến là cơ hội để các đệ tử cấp thấp đột phá bình cảnh.","thanhVien":[{"ten":"Phan Thanh","chucVu":"Đệ tử","tuChuong":"@c1274","trangThai":"đang hoạt động"},{"ten":"Nam tử cẩm bào họ Tần","chucVu":"Đệ tử","tuChuong":"@c1274","trangThai":"đang hoạt động"},{"ten":"Nam thanh niên đi cùng họ Tần","chucVu":"Đệ tử","tuChuong":"@c1274","trangThai":"đang hoạt động"},{"ten":"Nữ thanh niên đi cùng họ Tần","chucVu":"Đệ tử","tuChuong":"@c1274","trangThai":"đang hoạt động"}],"quanHe":"Có giao tình với cao tầng An Viễn Thành.","trangThai":"Phái đệ tử hỗ trợ chống thú triều","capNhatToi":"@c1274","tabs":{"tienTrinh":[{"chuong":"@c1274","loai":"liên minh","importance":"normal","giaiDoan":"Viện trợ An Viễn Thành","text":"Kim Ngọc Tông phái bốn đệ tử Trúc Cơ đến trợ giúp An Viễn Thành chống thú triều.","anchor":"Cẩm bào nam tử cùng với mấy người Phan Thanh đều là phụng mệnh sư môn tới hiệp trợ An Viễn Thành để chống lại thú triều lần này.","trangThaiMoc":"Đang hỗ trợ phòng thủ"}]},"nguon":["@c1274"]},{"id":"hon-muoi-tieu-tong-mon","name":"Hơn mười tiểu tông môn","cn":"","type":"nhóm tông môn","typeLabel":"Liên nhóm tông môn nhỏ","diaBan":"Khu vực quanh An Viễn Thành","nhanVatChinh":[],"blurb":"Nhóm hơn mười tông môn nhỏ cùng đưa đệ tử tới An Viễn Thành.","detail":"Ngoài Kim Ngọc Tông, hơn mười tiểu tông môn khác cũng phái đệ tử đến hỗ trợ An Viễn Thành đối phó thú triều.","trangThai":"Đang viện trợ An Viễn Thành","capNhatToi":"@c1274","tabs":{"tienTrinh":[{"chuong":"@c1274","loai":"liên minh","importance":"normal","giaiDoan":"Tập trung chống thú triều","text":"Hơn mười tiểu tông môn đưa đệ tử tới An Viễn Thành để tham gia chống thú triều.","anchor":"Đương nhiên phụng mệnh đến An Viễn Thành này không chỉ có mỗi Kim Ngọc Tông, còn có các đệ tử của hơn mười tiểu tông môn khác.","trangThaiMoc":"Đang viện trợ thành trì"}]},"nguon":["@c1274"]},{"id":"luc-luong-phong-thu-an-vien-thanh","name":"Lực lượng phòng thủ An Viễn Thành","cn":"","aliases":[],"type":"quan-su","typeLabel":"Lực lượng quân sự","diaBan":"An Viễn Thành","nhanVatChinh":["Thành chủ An Viễn Thành","Thanh cốt giáp sĩ thuộc An Viễn Thành","Hàn Lập","Tần Kỳ Quyền","Đại hán đầu bóng họ Uông"],"blurb":"Lực lượng quân sự bảo vệ An Viễn Thành, gồm tu sĩ, luyện thể sĩ và vệ binh, được phân thành tuyến phòng không và tuyến chống yêu thú mặt đất. Khi tường thành bị phá, quân phòng thủ tại lỗ hổng chịu tổn thất nặng, còn các tu sĩ lần lượt từ bỏ phòng thủ.","detail":"Khi ba đàn thú áp sát An Viễn Thành, thành chủ tập trung tu sĩ để giám sát và đối phó phi cầm, đồng thời giao nhiệm vụ chống Thanh Lang và Xích Mãng cho luyện thể sĩ cùng vệ binh; những người mới chiêu mộ được chỉnh đốn để luân phiên tác chiến (@c1275). Đến khi tường thành bị phá, lực lượng trấn giữ lỗ hổng chịu tổn thất nặng và các tu sĩ lần lượt rời bỏ vị trí phòng thủ, khiến thế phòng vệ suy yếu (@c1281).","lanhDaoHienThoi":"Thành chủ An Viễn Thành","thanhVien":[{"ten":"Thành chủ An Viễn Thành","chucVu":"Người chỉ huy","tuChuong":"@c1275","trangThai":"Đang chỉ huy"},{"ten":"Thanh cốt giáp sĩ thuộc An Viễn Thành","chucVu":"Giáp sĩ trinh sát và truyền lệnh","tuChuong":"@c1275","trangThai":"Đang thi hành nhiệm vụ"}],"trangThai":"Tan rã","capNhatToi":"@c1275","tabs":{"tienTrinh":[{"chuong":"@c1275","loai":"khai chiến","importance":"major","giaiDoan":"Triển khai chống ba đàn thú","text":"Lực lượng phòng thủ tập trung tu sĩ đối phó phi cầm, đồng thời giao Thanh Lang và Xích Mãng cho luyện thể sĩ cùng vệ binh.","anchor":"ngươi đem những tu sĩ kia an bài chung một chổ, chuyên môn giám thị động tĩnh đám phi cầm kia"},{"chuong":"@c1281","loai":"suy","importance":"major","giaiDoan":"Phòng tuyến tan rã","text":"Tường thành bị phá, lực lượng tại lỗ hổng chịu tổn thất nặng và các tu sĩ lần lượt từ bỏ phòng thủ.","anchor":"Giờ phút này An Viễn Thành đã bị thất thủ","trangThaiMoc":"Tan rã"}]},"nguon":["@c1275","@c1281"],"dacDiem":"Lực lượng hỗn hợp gồm tu sĩ, luyện thể sĩ và vệ binh, được phân công phòng thủ theo mục tiêu trên không và dưới mặt đất.","congNang":["Giám sát và đối phó phi cầm bằng lực lượng tu sĩ (@c1275)","Chống Thanh Lang và Xích Mãng trên mặt đất bằng luyện thể sĩ cùng vệ binh (@c1275)","Chỉnh đốn người mới chiêu mộ để luân phiên tác chiến (@c1275)"]},{"id":"linh-doi","name":"Linh đội","cn":"","type":"don-vi-quan-su","typeLabel":"Đơn vị luyện thể sĩ","diaBan":"An Viễn Thành","nhanVatChinh":[],"blurb":"Đơn vị cứu viện gồm hơn trăm luyện thể sĩ mặc cốt giáp và sử dụng các loại linh cụ đao kiếm.","detail":"Linh đội xuất hiện khi lực lượng trên thành gần mất khả năng chống cự. Các thành viên nhanh chóng chém giết thanh lang, phân thây cự lang biến dị và cử hơn mười người bay lên vây yêu lang.","quyMo":"Hơn trăm luyện thể sĩ","tranPhai":"Cốt giáp và các loại đê giai linh cụ đao kiếm","trangThai":"Đang tham gia phòng thủ An Viễn Thành","tabs":{"tienTrinh":[{"chuong":"@c1278","loai":"khai chiến","importance":"normal","giaiDoan":"Tiếp viện phòng tuyến","text":"Hơn trăm luyện thể sĩ của linh đội tiến lên thành, nhanh chóng đánh lui đàn sói và vây con yêu lang trên không.","anchor":"trên thành đầu bất chợt xuất hiện hơn trăm tên luyện thể sĩ"}]},"capNhatToi":"@c1278","nguon":["@c1278"]},{"id":"doi-tu-si-phong-thu-vien-an-thanh","name":"Đội tu sĩ phòng thủ Viễn An Thành","cn":"","type":"lien-minh-lam-thoi","typeLabel":"Lực lượng tu sĩ phòng thủ","diaBan":"Viễn An Thành","nhanVatChinh":["Đại hán đầu bóng","Nam tử cẩm bào họ Tần"],"blurb":"Đội ngũ hơn trăm tu sĩ tập hợp để bảo vệ Viễn An Thành trước thú triều.","detail":"Phần lớn thành viên có tu vi Trúc Cơ kỳ. Hai tu sĩ Trúc Cơ hậu kỳ là đại hán đầu bóng và cẩm bào nam tử của Kim Ngọc Tông đứng đầu đội hình, dẫn mọi người giao chiến với Báo Cầm Thú trên không.","quyMo":"Hơn trăm tu sĩ","caoThuManhNhat":"Hai tu sĩ Trúc Cơ hậu kỳ","soCaoThu":"Hai người đứng đầu có tu vi Trúc Cơ hậu kỳ","thanhVien":[{"ten":"Đại hán đầu bóng","chucVu":"Chỉ huy","tuChuong":"@c1280","trangThai":"đang tham chiến"},{"ten":"Nam tử cẩm bào họ Tần","chucVu":"Chỉ huy","tuChuong":"@c1280","trangThai":"đang tham chiến"}],"tabs":{"tienTrinh":[{"chuong":"@c1280","loai":"khai chiến","importance":"normal","giaiDoan":"Thú triều công thành","text":"Hơn trăm tu sĩ bay tới tường thành và giao chiến với đàn Báo Cầm Thú trên không.","anchor":"Đây chính là các tu tiên giả ẩn trú trong toà thành","trangThaiMoc":"Đang phòng thủ Viễn An Thành"}]},"trangThai":"Đang tham chiến","capNhatToi":"@c1280","nguon":["@c1280"]},{"id":"thu-trieu-cong-pha-an-vien-thanh","name":"Thú triều công phá An Viễn Thành","cn":"","type":"liên quân yêu thú","typeLabel":"Thú triều","diaBan":"An Viễn Thành","nhanVatChinh":[],"blurb":"Thú triều công phá An Viễn Thành là liên quân gồm bốn loại yêu thú đến từ khu vực quanh thành và Thanh La Sa Mạc. Chúng phối hợp phá vỡ phòng tuyến, tràn vào trong thành và buộc lực lượng phòng thủ phải giải tán. @c1281","detail":"Thú triều hình thành từ các đàn yêu thú quanh An Viễn Thành và Thanh La Sa Mạc, gồm Báo Cầm Thú, Xích Mãng, hàng trăm biến dị cự mãng và Sa Trùng Thú. Khi khai chiến, Báo Cầm Thú ngưng tụ lục sắc yêu vụ phá sập tường thành, mở đường cho Xích Mãng cùng đàn biến dị cự mãng tràn vào; Sa Trùng Thú từ Thanh La Sa Mạc tiếp tục áp sát, khiến phòng tuyến bị phá vỡ và lực lượng phòng thủ phải giải tán. @c1281","nguonGoc":"Các đàn yêu thú quanh An Viễn Thành và Thanh La Sa Mạc","quyMo":"Bốn loại thú liên thủ","quanHe":"Đối địch với An Viễn Thành","trangThai":"Đã công phá An Viễn Thành","capNhatToi":"@c1281","tabs":{"tienTrinh":[{"chuong":"@c1281","loai":"khai chiến","importance":"major","giaiDoan":"Công phá An Viễn Thành","text":"Bốn loại thú liên thủ phá vỡ phòng tuyến và tràn vào An Viễn Thành.","anchor":"Lần này dưới bốn chủng loại thú liên thủ, An Viễn Thành tiêu rồi","trangThaiMoc":"Chiếm ưu thế"}]},"nguon":["@c1281"],"uyLuc":"Liên quân bốn loại yêu thú đã phá sập tường thành, xuyên thủng phòng tuyến, tràn vào An Viễn Thành và buộc lực lượng phòng thủ giải tán. @c1281","dacDiem":"Thú triều gồm bốn loại yêu thú phối hợp tiến công, trong đó Báo Cầm Thú phá thành mở đường, Xích Mãng và đàn biến dị cự mãng tràn vào, còn Sa Trùng Thú từ Thanh La Sa Mạc tiếp tục áp sát. @c1281","congNang":["Báo Cầm Thú ngưng tụ lục sắc yêu vụ, phá sập tường thành và mở đường tiến công. @c1281","Xích Mãng cùng hàng trăm biến dị cự mãng theo lối mở tràn vào An Viễn Thành. @c1281","Sa Trùng Thú từ Thanh La Sa Mạc áp sát, gia tăng sức ép khiến lực lượng phòng thủ phải giải tán. @c1281","Bốn loại yêu thú phối hợp phá vỡ phòng tuyến và xâm nhập An Viễn Thành. @c1281"]},{"id":"thien-nguyen-thanh","name":"Thiên Nguyên Thành","cn":"","type":"thanh-thi-quan-ly","typeLabel":"Thế lực quản lý của Nhân tộc","diaBan":"Thiên Nguyên Thành và khu vực chịu sự quản lý","nhanVatChinh":[],"blurb":"Thiên Nguyên Thành là trung tâm có các cao giai tu sĩ quản lý khu vực của Nhân tộc. Sau khi An Viễn Thành bị hủy diệt, nơi đây phái nhiều người đến điều tra nguyên nhân.","detail":"Tai họa tại An Viễn Thành đủ nghiêm trọng để kinh động các cao giai tu sĩ ở Thiên Nguyên Thành. Một lực lượng điều tra được phái tới vì việc cả tòa thành bị yêu thú phá hủy không phải hiện tượng thường thấy.","quyMo":"Có nhiều cao giai tu sĩ và khả năng điều động người đi điều tra","trangThai":"Đang điều tra biến cố An Viễn Thành","capNhatToi":"@c1282","tabs":{"tienTrinh":[{"chuong":"@c1282","loai":"nhắc tới","importance":"normal","giaiDoan":"Điều tra An Viễn Thành","text":"Các cao giai tu sĩ tại Thiên Nguyên Thành bị kinh động và phái người điều tra nguyên nhân An Viễn Thành thất thủ.","anchor":"Vì vậy đã kinh động đến cao giai tu sĩ ở Thiên Nguyên Thành.","trangThaiMoc":"Phái người điều tra"}]},"nguon":["@c1282"]},{"id":"hac-phuong-toc","name":"Hắc Phượng Tộc","cn":"","type":"yeu-toc","typeLabel":"Thế lực Yêu tộc","diaBan":"Ngoài lãnh thổ Nhân tộc tam cảnh","nhanVatChinh":["Phiệt cô cô","Thiếu chủ Hắc Phượng Tộc","Đại Nhi"],"blurb":"Hắc Phượng Tộc là một thế lực Yêu tộc coi trọng việc bảo toàn huyết mạch, từng bí mật phái Phiệt cô cô tiến vào lãnh địa Nhân tộc để tìm Đại Nhi. Trong quá trình này, tộc đã liên thủ với các đàn thú công phá An Viễn Thành, sau đó truyền thừa cho Đại Nhi và đưa nàng rời khỏi lãnh địa Nhân tộc.","detail":"Đại Nhi là một bán yêu mang huyết mạch Hắc Phượng. Để tìm và đưa nàng trở về, Hắc Phượng Tộc cử Phiệt cô cô bí mật truy tìm, đồng thời liên thủ với các đàn thú công phá An Viễn Thành. Sau khi tìm được Đại Nhi, Phiệt cô cô tiến hành truyền thừa cho nàng rồi đưa nàng rời khỏi lãnh địa Nhân tộc nhằm bảo toàn huyết mạch Hắc Phượng. @c1284 @c1287","tonChi":"Không để huyết mạch của tộc lưu lạc trong tay Nhân tộc.","quanHe":"Đối địch với những người ngăn cản việc thu hồi Đại Nhi.","trangThai":"Đang tiếp nhận Đại Nhi về tộc","thanhVien":[{"ten":"Phiệt cô cô","chucVu":"Yêu tu bảo hộ huyết mạch","tuChuong":"@c1284","trangThai":"đang hoạt động"},{"ten":"Thiếu chủ Hắc Phượng Tộc","chucVu":"Thiếu chủ","tuChuong":"@c1284","trangThai":"không rõ"},{"ten":"Đại Nhi","chucVu":"Người thừa kế mang huyết mạch bán yêu","tuChuong":"@c1284","trangThai":"được tiếp nhận"},{"ten":"Chu Hồng","chucVu":"Hóa Hình yêu tu","tuChuong":"@c1357","trangThai":"đang hoạt động"},{"ten":"Tiểu Hồng","chucVu":"Thành viên","tuChuong":"@c1388","trangThai":"Đang thuộc tộc"},{"ten":"Tiêu Quán","chucVu":"Hắc Phượng Vương","tuChuong":"@c1797","trangThai":"đương nhiệm"},{"ten":"Tiểu Hồng","chucVu":"Thành viên","tuChuong":"@c1797","trangThai":"đang chịu phạt"}],"capNhatToi":"@c1284","tabs":{"tienTrinh":[{"chuong":"@c1284","loai":"khai chiến","importance":"normal","giaiDoan":"Truy tìm Đại Nhi","text":"Hắc Phượng Tộc liên thủ với các đàn thú công phá An Viễn Thành và cử Phiệt cô cô truy tìm Đại Nhi để thu hồi huyết mạch của tộc.","anchor":"Hừ, huyết mạch bổn tộc có thể nào lại để lưu lạc trong tay Nhân tộc được chứ","trangThaiMoc":"Đang bí mật truy tìm Đại Nhi"},{"chuong":"@c1287","loai":"mở rộng/mất địa bàn","importance":"normal","giaiDoan":"Tiếp nhận Đại Nhi","text":"Phiệt cô cô truyền thừa cho Đại Nhi và đưa nàng rời khỏi lãnh địa nhân loại để bảo toàn huyết mạch Hắc Phượng Tộc.","anchor":"dù thế nào ta cũng phải bảo trì huyết mạch của Hắc Phượng Tộc chúng ta","trangThaiMoc":"Tiếp nhận Đại Nhi về tộc"}]},"nguon":["@c1284","@c1287","@c1357","@c1388","@c1797"],"uyLuc":"Hắc Phượng Tộc từng liên thủ với các đàn thú công phá An Viễn Thành. @c1284","dacDiem":"Coi trọng việc thu hồi và bảo toàn huyết mạch Hắc Phượng, kể cả huyết mạch tồn tại trên một bán yêu sống trong lãnh địa Nhân tộc.","congNang":["Có thể truyền thừa cho người mang huyết mạch Hắc Phượng. @c1287"]},{"id":"long-hung-thuong-hoi","name":"Long Hưng Thương Hội","cn":"","aliases":[],"type":"thuong-hoi","typeLabel":"Thương hội","diaBan":"Ngu Dương Thành","nhanVatChinh":["Phạm lão đệ","Hàn Lập"],"blurb":"Hội đấu giá do Phạm lão đệ làm chủ tại Ngu Dương Thành. Nhờ mười năm được Hàn Lập bí mật chế tạo linh cụ, thương hội vươn lên thành một trong những hội đấu giá lớn nhất thành.","detail":"Long Hưng Thương Hội vốn là một thương hội mới nổi nhưng phát triển mạnh nhờ các linh cụ do Hàn Lập chế tạo dưới thân phận Hàn đại sư. Khi Hàn Lập rời đi, thương hội đã có nhiều học đồ được truyền hơn nửa y bát chế tạo linh cụ và nhận thêm Trường kiếm Kim Giao, vật phẩm có thể giúp họ tranh quyền độc quyền buôn bán.","lanhDaoHienThoi":"Phạm lão đệ","quyMo":"Một trong những hội đấu giá lớn nhất Ngu Dương Thành","tranPhai":"Trường kiếm Kim Giao được Phạm lão đệ dự định dùng làm vật trấn môn.","trangThai":"Đang hoạt động","thanhVien":[{"ten":"Phạm lão đệ","chucVu":"Chủ nhân","tuChuong":"@c1288","trangThai":"Đang tại vị"},{"ten":"Hàn Lập","chucVu":"Linh cụ đại sư bí mật","tuChuong":"@c1288","trangThai":"Đã rời đi"},{"ten":"Phùng Nhị","chucVu":"Người hầu","tuChuong":"@c1288","trangThai":"Đang phục vụ"}],"lanhDaoMoc":[{"ten":"Phạm lão đệ","tuChuong":"@c1288","denChuong":""}],"capNhatToi":"@c1288","tabs":{"tienTrinh":[{"chuong":"@c1288","loai":"mở rộng/mất địa bàn","importance":"normal","giaiDoan":"Trở thành hội đấu giá hàng đầu","text":"Sau mười năm nhận được sự trợ giúp bí mật của Hàn Lập, Long Hưng Thương Hội đã trở thành một trong những hội đấu giá lớn nhất Ngu Dương Thành. Hàn Lập sau đó chấm dứt việc chế tạo linh cụ cho thương hội và rời đi.","anchor":"Hôm nay, Long Hưng Thương Hội đã trở thành một trong những hội đấu giá lớn nhất tòa thành này rồi"}]},"nguon":["@c1288"]},{"id":"dau-gia-thuong-hoi","name":"Đấu Giá Thương Hội","cn":"","type":"thuong-hoi","typeLabel":"Thương hội","diaBan":"Ngu Dương Thành","nhanVatChinh":["Hàn Lập","Phạm lão đệ"],"blurb":"Thương hội tại Ngu Dương Thành từng được Hàn Lập âm thầm hỗ trợ.","detail":"Sau khi được Phạm lão đệ cứu và đưa về Ngu Dương Thành, Hàn Lập âm thầm góp sức giúp Đấu Giá Thương Hội phát triển nhanh chóng.","quanHe":"Được Hàn Lập hỗ trợ phát triển.","trangThai":"Đang hoạt động","thanhVien":[{"ten":"Phạm lão đệ","chucVu":"Tiểu thương nhân có liên hệ với thương hội","tuChuong":"@c1289","trangThai":"đang hoạt động"}],"tabs":{"tienTrinh":[{"chuong":"@c1289","loai":"mở rộng","importance":"normal","giaiDoan":"Phát triển tại Ngu Dương Thành","text":"Đấu Giá Thương Hội phát triển nhanh chóng nhờ sự hỗ trợ âm thầm của Hàn Lập.","anchor":"âm thầm xuất lực đem Đấu Giá Thương Hội phát triển một cách nhanh chóng"}]},"capNhatToi":"@c1289","nguon":["@c1289"]},{"id":"nhan-toc","name":"Nhân tộc","cn":"","type":"chung-toc","typeLabel":"Chủng tộc","diaBan":"Thiên Nguyên Cảnh và vùng giáp ranh Nhân–Yêu","nhanVatChinh":["Hàn Lập","Thiên Nguyên Thánh Hoàng"],"blurb":"Nhân tộc là một trong hai thế lực lớn hiện diện quanh vùng giáp ranh cùng Yêu tộc. Cao tầng Nhân tộc hạn chế lực lượng cấp cao tiến vào khu vực này nhằm tránh kích động một cuộc đại chiến giữa hai tộc.","detail":"Tại vùng giáp ranh, cao tầng Nhân tộc cùng phía Yêu tộc duy trì sự kiềm chế bằng cách hạn chế lực lượng cấp cao tiến vào, qua đó ngăn xung đột leo thang thành đại chiến. @c1290","quanHe":"Duy trì thế cân bằng và kiềm chế với Yêu tộc tại vùng giáp ranh.","trangThai":"Hạn chế lực lượng cấp cao tiến vào vùng biên","tabs":{"tienTrinh":[{"chuong":"@c1290","loai":"nhắc tới","importance":"normal","giaiDoan":"Kiềm chế tại vùng biên","text":"Cao tầng Nhân tộc cùng Yêu tộc hạn chế lực lượng cấp cao tiến vào vùng giáp ranh để tránh bùng nổ đại chiến.","anchor":"điều này làm cho lớp cao tầng của Nhân-Yêu lưỡng tộc cảm thấy kiêng kỵ, liền hạn chế Tu sĩ cấp cao vào chốn này","trangThaiMoc":"Kiềm chế lực lượng cấp cao"}]},"capNhatToi":"@c1290","nguon":["@c1290","@c1354","@c1876","@c1912","@c1917","@c1964","@c2006"],"thanhVien":[{"ten":"Hàn Lập","chucVu":"Thành viên đội thám sát","tuChuong":"@c1354","trangThai":"tham gia nhiệm vụ"},{"ten":"Lũng Đông","chucVu":"Người dẫn dắt nhóm Nhân Tộc","tuChuong":"@c1354","trangThai":"tham gia nhiệm vụ"},{"ten":"Diệp Dĩnh","chucVu":"Thành viên đội thám sát","tuChuong":"@c1354","trangThai":"tham gia nhiệm vụ"}],"dacDiem":"Là một trong hai thế lực lớn quanh vùng giáp ranh và duy trì chính sách kiềm chế đối với Yêu tộc.","congNang":["Hạn chế lực lượng cấp cao tiến vào vùng giáp ranh để tránh làm bùng nổ đại chiến với Yêu tộc. @c1290"]},{"id":"khung-vu-cat","name":"Khung Vũ Cát","cn":"","type":"Cửa hàng","typeLabel":"Cửa hàng","diaBan":"Lạc Nhật Thành","nhanVatChinh":["Tư lão"],"blurb":"Cửa hàng tại Lạc Nhật Thành, giao dịch theo thứ tự trước sau thay vì ưu tiên người trả giá cao hơn.","detail":"Khung Vũ Cát do Tư lão làm chưởng quỹ. Khi Hàn Lập hỏi mua Ngân Tâm Thạch trước, cửa hàng giữ quyền giao dịch cho hắn dù nữ tử họ Lữ muốn mua lại với giá cao hơn.","nguon":["@c1293"]},{"id":"linh-toc","name":"Linh Tộc","cn":"","type":"Chủng tộc","typeLabel":"Thế lực chủng tộc","diaBan":"","nhanVatChinh":["Thiên Anh","Hoàng Thạch Công"],"blurb":"Chủng tộc do Thiên Thu Thánh nữ đại diện trong cuộc giao dịch bí mật với Lũng gia. Tộc luật cấm tự tiện chuyển phế linh cho dị tộc. (+) Chủng tộc của Thiên Anh và Hoàng Thạch Công, coi Nhân Tộc và Yêu Tộc là đại địch. [CAN-SOAT-GOP]","detail":"Linh Tộc đang truy sát một kẻ phản nghịch và tìm cách thu hồi Thần Huyết trước khi vật trọng yếu này được giao cho Nhân Tộc. Nhiều nhánh trong tộc đã tham gia cuộc truy tìm tại Lạc Nhật Chi Mộ.","nguon":["@c1293","@c1807","@c2091"],"thanhVien":[{"ten":"Thiên Thu Thánh nữ","chucVu":"Thánh nữ, đại diện giao dịch","tuChuong":"@c1807","trangThai":"đang hoạt động"},{"ten":"Linh Vương","chucVu":"Vương","tuChuong":"@c2091","trangThai":"đang tại vị"},{"ten":"Bạch Thích","chucVu":"Hậu bối được giao nhiệm vụ","tuChuong":"@c2091","trangThai":"đang hoạt động"}],"tabs":{}},{"id":"ngu-hanh-linh-toc","name":"Ngũ Hành Linh Tộc","cn":"","type":"Nhánh chủng tộc","typeLabel":"Nhánh Linh Tộc","diaBan":"","nhanVatChinh":["Thiên Anh","Hoàng Thạch Công"],"blurb":"Một nhánh lớn của Linh Tộc đã điều động nhiều người tham gia cuộc truy tìm kẻ phản nghịch và Thần Huyết.","detail":"Ngũ Hành Linh Tộc coi việc thu hồi Thần Huyết là đại sự. Thủy Linh Tộc được nhắc đến như một thành phần thần bí trong hệ này và đặc biệt coi trọng vật đó.","nguon":["@c1293"]},{"id":"khi-linh-toc","name":"Khí Linh Tộc","cn":"","type":"Nhánh chủng tộc","typeLabel":"Nhánh Linh Tộc","diaBan":"","nhanVatChinh":["Húc Thiên"],"blurb":"Một dị tộc cử Thiên Thu thánh nữ mang hai trọng bảo tới đại hội đấu giá của Nhân Yêu lưỡng tộc. Toàn bộ linh thạch thu được từ việc bán bảo vật được dùng làm quà biểu thị thành ý. (+) Nhánh Linh Tộc có kẻ phản nghịch đang bị truy sát và cũng phái người tham gia cuộc truy tìm. [CAN-SOAT-GOP]","detail":"Kẻ phản nghịch mang theo vật trọng yếu xuất thân từ Khí Linh Tộc. Hoàng Thạch Công nghi ngờ người của nhánh này tham gia truy sát còn nhằm tranh đoạt Thần Huyết của Ngũ Hành Linh Tộc.","nguon":["@c1293","@c1297","@c1800"],"tabs":{"tienTrinh":[{"chuong":"@c1297","loai":"nhắc tới","importance":"normal","giaiDoan":"Đi tiếp viện Hỗn Độn Cốc","text":"Khí Linh Tộc phái lực lượng do Húc Thiên chỉ huy tới Hỗn Độn Cốc để tham gia truy bắt phản nghịch.","anchor":"Chỉ cần chờ cho lực lượng Khí Linh tộc đến đây, tên phản nghịch kia căn bản không còn đường trốn chạy"}]},"thanhVien":[{"ten":"Húc Thiên","chucVu":"Thủ lĩnh viện quân","tuChuong":"@c1297","trangThai":"đang hoạt động"},{"ten":"Thiên Thu thánh nữ","chucVu":"Thánh nữ","tuChuong":"@c1800","trangThai":"Đang đại diện tộc tham dự đại hội"}]},{"id":"lac-nhat-thanh","name":"Lạc Nhật Thành","cn":"","type":"thanh-tri","typeLabel":"Thế lực thành trì của Nhân Tộc","diaBan":"Khu vực cửa vào Lạc Nhật Chi Mộ do Nhân Tộc quản lý","nhanVatChinh":[],"blurb":"Lạc Nhật Thành bố trí tu sĩ bí mật giám sát cửa vào Lạc Nhật Chi Mộ thuộc phía Nhân Tộc.","detail":"Lực lượng giám sát quanh cửa hạp cốc được đồn có tu sĩ Kết Đan và một tu sĩ Hóa Thần trấn giữ.","quyMo":"Có lực lượng giám sát gồm tu sĩ từ Kết Đan tới Hóa Thần.","caoThuManhNhat":"Một tu sĩ Hóa Thần trấn giữ","thanhVien":[],"tabs":{"tienTrinh":[{"chuong":"@c1294","loai":"nhắc tới","importance":"normal","giaiDoan":"Giám sát cửa cổ mộ","text":"Lạc Nhật Thành bố trí tu sĩ ẩn mình quanh cửa hạp cốc và có một tu sĩ Hóa Thần trấn giữ.","anchor":"có một vị là Hóa Thần Kỳ tu sĩ trấn giữ","trangThaiMoc":"Đang giám sát cửa vào"}]},"trangThai":"Đang hoạt động","capNhatToi":"@c1294","nguon":["@c1294"]},{"id":"thuy-linh-toc","name":"Thủy Linh Tộc","cn":"","type":"chi-toc","typeLabel":"Nhánh Ngũ Hành Linh Tộc","diaBan":"Chưa rõ","nhanVatChinh":[],"blurb":"Thủy Linh Tộc là một trong những nhánh thần bí nhất thuộc Ngũ Hành Linh Tộc.","detail":"Tộc này đặc biệt coi trọng Thần Huyết và được dự đoán có thể đã phái một Linh Tương mạnh tham gia truy bắt phản nghịch.","nguonGoc":"Một nhánh thuộc Ngũ Hành Linh Tộc.","quyMo":"Chưa rõ","caoThuManhNhat":"Có thể có một Linh Tương tham gia cuộc truy bắt","quanHe":"Thuộc Ngũ Hành Linh Tộc và tham gia tranh chấp xoay quanh Thần Huyết.","thanhVien":[],"tabs":{"tienTrinh":[{"chuong":"@c1294","loai":"nhắc tới","importance":"bridge","giaiDoan":"Có thể điều động Linh Tương","text":"Thủy Linh Tộc được dự đoán có thể phái một Linh Tương mạnh đến vì Thần Huyết.","anchor":"Thủy Linh Tộc trong Ngũ hành của chúng ta là một trong những tộc thần bí nhất","trangThaiMoc":"Có thể đã tham gia truy bắt"}]},"trangThai":"Đang hoạt động","capNhatToi":"@c1294","nguon":["@c1294"]},{"id":"thanh-hoang-cung","name":"Thánh Hoàng Cung","cn":"","type":"trieu-dinh","typeLabel":"Thế lực Nhân Tộc","diaBan":"Chưa rõ","nhanVatChinh":["Đặc sứ Thánh Hoàng Cung"],"blurb":"Thế lực ban lệnh cho Lạc Nhật Thành tiếp ứng phản nghịch Linh Tộc và bảo toàn trọng vật người này mang theo.","detail":"Thánh Hoàng Cung còn phái một đặc sứ tới Lạc Nhật Thành để tiếp nhận trọng vật, nhưng hành trình của người này bị chậm do đường xa và các vết nứt không gian.","lanhDaoHienThoi":"Không rõ","quanHe":"Điều động Lạc Nhật Thành thực hiện nhiệm vụ tiếp ứng.","trangThai":"Đang can dự vào cuộc truy tìm phản nghịch Linh Tộc","thanhVien":[{"ten":"Đặc sứ Thánh Hoàng Cung","chucVu":"Đặc sứ","tuChuong":"@c1295","trangThai":"đang trên đường tới Lạc Nhật Thành"}],"tabs":{"tienTrinh":[{"chuong":"@c1295","loai":"nhắc tới","importance":"normal","giaiDoan":"Can dự cuộc tiếp ứng","text":"Thánh Hoàng Cung truyền lệnh cứu phản nghịch Linh Tộc, bảo toàn trọng vật và phái đặc sứ tới tiếp nhận.","anchor":"Bất quá, ta nhận được mệnh lệnh do Thánh Hoàng Cung truyền tới .","trangThaiMoc":"Can dự vào cuộc truy tìm"}]},"capNhatToi":"@c1295","nguon":["@c1295"]},{"id":"quynh-thu-toc","name":"Quỳnh Thử Tộc","cn":"","type":"yeu-toc","typeLabel":"Tộc thuộc Yêu Tộc","diaBan":"Chưa rõ","nhanVatChinh":["Thiếu niên họ Nghê"],"blurb":"Một tộc thuộc Yêu Tộc có hậu bối trẻ tuổi được đánh giá là thiên phú rất cao.","detail":"Thiếu niên họ Nghê đại diện Quỳnh Thử Tộc đề nghị kết đôi hậu bối này với Đại Nhi của Hắc Phượng Tộc để tạo hôn sự liên tộc.","tonChi":"Không rõ","lanhDaoHienThoi":"Không rõ","quanHe":"Đề xuất kết thân với Hắc Phượng Tộc.","trangThai":"Đang đề xuất hôn sự liên tộc","thanhVien":[{"ten":"Thiếu niên họ Nghê","chucVu":"Không rõ","tuChuong":"@c1295","trangThai":"đang hoạt động"}],"tabs":{"tienTrinh":[{"chuong":"@c1295","loai":"liên minh","importance":"normal","giaiDoan":"Đề xuất hôn sự","text":"Quỳnh Thử Tộc thông qua thiếu niên họ Nghê đề xuất kết đôi một hậu bối tài năng với Đại Nhi của Hắc Phượng Tộc.","anchor":"Quỳnh Thử Tộc chúng ta cũng xuất hiện ra một tên tuổi trẻ thiên phú thật tốt","trangThaiMoc":"Đề xuất kết thân với Hắc Phượng Tộc"}]},"capNhatToi":"@c1295","nguon":["@c1295"]},{"id":"da-xoa-toc","name":"Dạ Xoa Tộc","cn":"","type":"chung-toc","typeLabel":"Chủng tộc","diaBan":"Không rõ","nhanVatChinh":[],"blurb":"Một dị tộc có đội quân hơn trăm người bao vây đoàn tầm bảo Nhân tộc gần Linh Từ Thạch Mạch. (+) Chủng tộc đang giao chiến quy mô lớn với Linh Tộc và đã điều động nhiều Dạ Xoa Vương. [CAN-SOAT-GOP] (+) Một trong các tộc tham gia cục diện chiến tranh tại Linh giới. Lão quái Tang Hải của tộc này đã đồng ý với kế hoạch phản công do Mộc tộc chuẩn bị. [CAN-SOAT-GOP]","detail":"Dạ Xoa Tộc có khả năng hấp thu thiên địa linh khí mạnh mẽ, qua đó khắc chế nhiều thần thông của Linh Tộc. Sức ép của họ khiến ngay cả lực lượng Thánh Linh cũng chỉ có thể miễn cưỡng phòng thủ.","caoThuManhNhat":"Dạ Xoa Vương","soCaoThu":"Nhiều Dạ Xoa Vương tham chiến","quanHe":"Đối địch với Linh Tộc","tabs":{"tienTrinh":[{"chuong":"@c1297","loai":"khai chiến","importance":"normal","giaiDoan":"Giao chiến với Linh Tộc","text":"Dạ Xoa Tộc điều động nhiều Dạ Xoa Vương, ghìm chân cao thủ Linh Tộc trên chiến trường lớn.","anchor":"Dạ Xoa Tộc bên kia cũng xuất động vài tên Dạ Xoa Vương, chúng ta chỉ có thể miễn cưỡng ngăn cản đối phương công kích mà thôi"}]},"capNhatToi":"@c1297","nguon":["@c1297","@c1395","@c2151"],"aliases":["Tộc Dạ Xoa"],"thanhVien":[{"ten":"Nữ Dạ Xoa chỉ huy","chucVu":"Chỉ huy đội vây giết","tuChuong":"@c1395","trangThai":"đang hoạt động"},{"ten":"Hai Dạ Xoa khổng lồ chặn cơn lốc","chucVu":"Chiến lực phá vây","tuChuong":"@c1395","trangThai":"đang hoạt động"},{"ten":"Hai Dạ Xoa cấp cao","chucVu":"Cường giả chưa rõ thân phận","tuChuong":"@c1395","trangThai":"đang hoạt động"},{"ten":"Tang Hải","chucVu":"Lão quái","tuChuong":"@c2151","trangThai":"đang hoạt động"}]},{"id":"kim-linh-toc","name":"Kim Linh Tộc","cn":"","type":"chung-toc","typeLabel":"Nhánh Linh Tộc","diaBan":"Không rõ","nhanVatChinh":["Thiết Nhận"],"blurb":"Một nhánh của Linh Tộc có Thiết Nhận tham chiến tại Hỗn Độn Cốc.","detail":"Thiết Nhận được xác nhận là thành viên Kim Linh Tộc và trực tiếp đối đầu với đỉnh cấp Luyện thể sĩ của Nhân tộc.","thanhVien":[{"ten":"Thiết Nhận","chucVu":"","tuChuong":"@c1301","trangThai":"đang hoạt động"}],"capNhatToi":"@c1301","nguon":["@c1301"]},{"id":"lang-toc","name":"Lang tộc","cn":"","type":"yeu-toc","typeLabel":"Yêu tộc","diaBan":"Không rõ","nhanVatChinh":["Ba thanh niên gầy ốm, đen nhẻm","Tam Thủ Nguyệt Lang"],"blurb":"Tộc Yêu tu có ba thành viên hiện diện trong Hỗn Độn Cốc và có thể dung hợp thành Tam Thủ Yêu Lang.","detail":"Ba Yêu tu Lang tộc dung hợp bản thể để chống lại Thượng Cổ Cự Nhân nhưng vẫn bị áp đảo, phải nhờ Hoàng Thiên Kỳ cứu khỏi vùng hấp lực.","thanhVien":[{"ten":"Ba thanh niên gầy ốm, đen nhẻm","chucVu":"Yêu tu","tuChuong":"@c1304","trangThai":"đang hoạt động"}],"tabs":{"tienTrinh":[{"chuong":"@c1304","loai":"nhắc tới","importance":"normal","giaiDoan":"Ba thành viên lâm nguy","text":"Ba Yêu tu Lang tộc dung hợp thành Tam Thủ Yêu Lang nhưng bị Thượng Cổ Cự Nhân áp đảo.","anchor":"Ba tên Yêu tu này trong tình huống khẩn cấp đã dung hợp lại trở thành bản thể Tam Thủ Yêu Lang.","trangThaiMoc":"Ba thành viên được cứu sống"}]},"capNhatToi":"@c1304","nguon":["@c1304"]},{"id":"lac-thu-toc","name":"Lạc Thử Tộc","cn":"","type":"yeu-toc","typeLabel":"Yêu tộc","diaBan":"Không rõ","nhanVatChinh":["Hoàng Thiên Kỳ"],"blurb":"Yêu tộc có Hoàng Thiên Kỳ giữ chức trưởng lão.","detail":"Thực lực của tộc được thể hiện qua Hoàng Thiên Kỳ, người đủ sức can thiệp vào cuộc đối đầu với Thượng Cổ Cự Nhân và cứu Tam Thủ Yêu Lang.","lanhDaoHienThoi":"Không rõ","caoThuManhNhat":"Hoàng Thiên Kỳ","thanhVien":[{"ten":"Hoàng Thiên Kỳ","chucVu":"Trưởng lão","tuChuong":"@c1304","trangThai":"đang hoạt động"}],"tabs":{"tienTrinh":[{"chuong":"@c1304","loai":"nhắc tới","importance":"bridge","giaiDoan":"Lộ diện trưởng lão","text":"Hoàng Thiên Kỳ được xác nhận là trưởng lão của Lạc Thử Tộc.","anchor":"Đây chính tên trưởng lão của Lạc Thử Tộc, Hoàng Thiên Kỳ.","trangThaiMoc":"Đang hoạt động"}]},"capNhatToi":"@c1304","nguon":["@c1304"]},{"id":"yeu-nhan-luong-toc","name":"Yêu nhân lưỡng tộc","cn":"","type":"chủng tộc","typeLabel":"Liên xưng hai tộc","diaBan":"Khu vực quanh Lạc Nhật Chi Mộ","nhanVatChinh":[],"blurb":"Cách gọi chung Yêu tộc và Nhân tộc trong nhận định của những người truy đuổi Hàn Lập.","detail":"Khu vực quanh Lạc Nhật Chi Mộ được xem là địa bàn của Yêu tộc và Nhân tộc, khiến Húc Thiên cùng Linh Tộc không có lợi thế lưu lại lâu dài.","trangThai":"hoạt động","capNhatToi":"@c1308","nguon":["@c1308"]},{"id":"thuong-hao-cua-hoa-lao","name":"Thương hào của Hỏa lão","cn":"","type":"thuong-hoi","typeLabel":"Thế lực thương nghiệp","diaBan":"Xuyên Vân Sơn","nhanVatChinh":["Hỏa lão","Trung niên kỵ sĩ cưỡi cự lang trắng","Mấy vị tiên sư Kết Đan của thương đội"],"blurb":"Một thương hào tổ chức đoàn kỵ sĩ và thú xa vượt qua Xuyên Vân Sơn. Thương hào thanh trừ yêu thú, thuê tu sĩ Kết Đan dò xét cự sơn và dự định mở một thương lộ mới.","detail":"Đoàn người của thương hào gồm kỵ sĩ cưỡi cự lang, nhiều thú xa và các tiên sư Kết Đan. Sau khi nhận báo cáo khu vực ngàn dặm quanh Xuyên Vân Sơn đã được thanh trừ, Hỏa lão cho đoàn tiếp tục tiến lên để khai thông thương lộ.","dinhDanh":"goc","tonChi":"Tổ chức vận chuyển và mở thương lộ qua Xuyên Vân Sơn.","lanhDaoHienThoi":"Hỏa lão","quanHe":"Thuê các tu sĩ Kết Đan dò xét và hộ tống thương đội.","trangThai":"Đang mở thương lộ mới","thanhVien":[{"ten":"Hỏa lão","chucVu":"Người điều hành đoàn","tuChuong":"@c1309","trangThai":"Đang hoạt động"},{"ten":"Trung niên kỵ sĩ cưỡi cự lang trắng","chucVu":"Kỵ sĩ thuộc thương đội","tuChuong":"@c1309","trangThai":"Đang hoạt động"},{"ten":"Mấy vị tiên sư Kết Đan của thương đội","chucVu":"Tu sĩ dò xét và hộ tống","tuChuong":"@c1309","trangThai":"Đang hoạt động"}],"lanhDaoMoc":[{"ten":"Hỏa lão","tuChuong":"@c1309","denChuong":""}],"capNhatToi":"@c1309","tabs":{"tienTrinh":[{"chuong":"@c1309","loai":"mở rộng/mất địa bàn","importance":"normal","giaiDoan":"Mở thương lộ Xuyên Vân Sơn","trangThaiMoc":"Khu vực quanh Xuyên Vân Sơn đã được thanh trừ để thương đội tiến qua.","text":"Thương hào tổ chức thanh trừ yêu thú, cho tu sĩ Kết Đan dò xét cự sơn và chuẩn bị khai thông một thương lộ mới.","anchor":"Như vậy Bản thương hào lại mở ra một thương lộ mới"}]},"nguon":["@c1309"]},{"id":"thien-uyen-ve","name":"Thiên Uyên Vệ","cn":"","type":"quan-doan","typeLabel":"Lực lượng tu sĩ","diaBan":"Thiên Uyên Thành","nhanVatChinh":["Bạch diện Thiên Uyên Vệ","Thiên Uyên Vệ râu dê"],"blurb":"Lực lượng tu sĩ thuộc Thiên Uyên Thành, có thành viên cấp Luyện Hư và sử dụng Thuyền Kim Đình. (+) Hệ thống lực lượng phòng vệ hoạt động quanh các thạch tháp của Thiên Uyên thành. [CAN-SOAT-GOP]","detail":"Hai Thiên Uyên Vệ phát hiện động tĩnh thiên kiếp, truyền tống tới hỗ trợ Hàn Lập rồi yêu cầu hắn tới Thiên Uyên Thành thực hiện nghĩa vụ của tu sĩ phi thăng.","thanhVien":[{"ten":"Bạch diện Thiên Uyên Vệ","chucVu":"Thiên Uyên Vệ","tuChuong":"@c1311","trangThai":"đang-tại-vị"},{"ten":"Thiên Uyên Vệ râu dê","chucVu":"Thiên Uyên Vệ","tuChuong":"@c1311","trangThai":"đang-tại-vị"},{"ten":"Hàn Lập","chucVu":"Cựu thành viên","tuChuong":"@c1762","trangThai":"Đã rời"}],"tranPhai":"Thuyền Kim Đình","trangThai":"Đang hoạt động","tabs":{"tienTrinh":[{"chuong":"@c1311","loai":"nhắc tới","importance":"normal","giaiDoan":"Tiếp nhận tu sĩ phi thăng","text":"Hai thành viên Thiên Uyên Vệ truyền tống tới phá kiếp vân và chuẩn bị đưa Hàn Lập về Thiên Uyên Thành.","anchor":"Những vị Thiên Uyên Vệ này chắc chắn là nhận ra được nơi này có thiên kiếp động tĩnh, vì vậy mới vội vã trực tiếp truyền tống tới đây để hỗ trợ","trangThaiMoc":"Đang hoạt động"}]},"capNhatToi":"@c1311","nguon":["@c1311","@c1762"]},{"id":"thanh-minh-ve","name":"Thanh Minh Vệ","cn":"","type":"lực lượng tu sĩ","typeLabel":"Lực lượng tu sĩ","diaBan":"Thiên Uyên Thành","nhanVatChinh":[],"blurb":"Đơn vị mặc thanh giáp thuộc hệ thống phòng vệ của Thiên Uyên Thành, có đội ngũ được huấn luyện nghiêm ngặt. (+) Lực lượng phòng vệ hoạt động tại các thạch tháp của Thiên Uyên thành. [CAN-SOAT-GOP]","detail":"Thanh Minh Vệ hoạt động trong khu vực phòng vệ của Thiên Uyên Thành. Đơn vị đang thiếu một thành viên khi Hàn Lập được đưa tới; hắn được dự kiến bổ sung vào vị trí này và có khả năng trở thành đội trưởng. Các Thanh Minh Vệ xuất hiện trong thông đạo giữ hàng ngũ chỉnh tề và chỉ đứng tại chỗ quan sát người mới đến.","nguon":["@c1312","@c1762"],"thanhVien":[{"ten":"Hàn Lập","chucVu":"Cựu Thanh Minh vệ","tuChuong":"@c1762","trangThai":"Đã rời"},{"ten":"Nhạc đạo hữu","chucVu":"Thanh Minh vệ","tuChuong":"@c1762","trangThai":"Đang phục vụ"},{"ten":"Hứa Thiên Vũ","chucVu":"Thanh Minh vệ dẫn đội","tuChuong":"@c1762","trangThai":"Đang phục vụ"},{"ten":"Đinh huynh","chucVu":"Thanh Minh vệ","tuChuong":"@c1762","trangThai":"Đang phục vụ"}],"tabs":{}},{"id":"truong-lao-hoi","name":"Trưởng Lão hội","cn":"","type":"hoi-dong","typeLabel":"Cơ cấu quản lý","diaBan":"Thiên Uyên Thành","nhanVatChinh":[],"blurb":"Cơ cấu có quyền trực tiếp tiếp nhận và bổ nhiệm phi thăng tu sĩ tại Thiên Uyên Thành. (+) Cơ cấu quyền lực lựa chọn nhân sự cho nhiệm vụ thám sát Hắc Thạch Sâm Lâm. [CAN-SOAT-GOP] (+) Cơ quan điều động nhân sự và ban thưởng cho các nhiệm vụ phòng bị tại Thiên Uyên Thành. [CAN-SOAT-GOP]","detail":"Phi thăng tu sĩ không cần trải qua khảo hạch mà được Trưởng Lão hội trực tiếp bổ nhiệm làm Thanh Minh Vệ.","tonChi":"Quản lý và bổ nhiệm lực lượng tu sĩ tại Thiên Uyên Thành","quanHe":"Trực tiếp bổ nhiệm phi thăng tu sĩ làm Thanh Minh Vệ.","trangThai":"Đang hoạt động","capNhatToi":"@c1313","tabs":{"tienTrinh":[{"chuong":"@c1313","loai":"nhắc tới","importance":"normal","giaiDoan":"Bổ nhiệm phi thăng tu sĩ","text":"Trưởng Lão hội được xác nhận có quyền trực tiếp bổ nhiệm phi thăng tu sĩ làm Thanh Minh Vệ mà không cần khảo hạch.","anchor":"đều được Trưởng Lão hội trực tiếp bổ nhiệm làm Thanh Minh Vệ","trangThaiMoc":"đang hoạt động"},{"chuong":"@c1350","loai":"nhắc tới","importance":"bridge","giaiDoan":"Phụ trách biến động lớn","text":"Hàn Lập giao việc xử lý các biến động liên quan đến dị tộc cho Trưởng lão hội.","anchor":"Còn những chuyện khác, tự nhiên đã có Trưởng lão hội đứng ra xử lý.","trangThaiMoc":"Đang phụ trách tình hình bất thường"}]},"nguon":["@c1313","@c1350","@c1354","@c1877"],"thanhVien":[{"ten":"Hàn Lập","chucVu":"Người được cử làm nhiệm vụ","tuChuong":"@c1354","trangThai":"đang thực hiện nhiệm vụ"},{"ten":"Diệp Dĩnh","chucVu":"Người được cử làm nhiệm vụ","tuChuong":"@c1354","trangThai":"đang thực hiện nhiệm vụ"}]},{"id":"ngoc-khuyet-cac","name":"Ngọc Khuyết Các","cn":"","type":"cơ-quan","typeLabel":"Cơ quan quản lý linh địa","diaBan":"Thiên Uyên Thành","nhanVatChinh":["Thanh bào trung niên","Nữ tu xinh đẹp tuyệt trần","Tử bào đại hán","Thị nữ áo cung trang"],"blurb":"Cơ quan quản lý việc phân phối linh địa và động phủ tại Thiên Uyên Thành. Người xin linh địa phải giao tài vật để được xét tư cách trước khi lựa chọn vị trí.","detail":"Ngọc Khuyết Các có ít nhất ba tầng và phân luồng người xin linh địa theo cấp tu vi. Tầng một phục vụ Hắc Thiết vệ, còn tầng hai có tu sĩ Luyện Hư phụ trách xét tài vật của tu sĩ Hóa Thần.","quyMo":"Cơ sở có ít nhất ba tầng.","lanhDaoHienThoi":"Không rõ","thanhVien":[{"ten":"Thanh bào trung niên","chucVu":"Người xét tư cách tại tầng một","tuChuong":"@c1315","trangThai":"Đang làm việc"},{"ten":"Nữ tu xinh đẹp tuyệt trần","chucVu":"Người tiếp đón","tuChuong":"@c1315","trangThai":"Đang làm việc"},{"ten":"Tử bào đại hán","chucVu":"Người xét tư cách tại tầng hai","tuChuong":"@c1315","trangThai":"Đang làm việc"},{"ten":"Thị nữ áo cung trang","chucVu":"Người giới thiệu linh địa","tuChuong":"@c1315","trangThai":"Đang làm việc"}],"trangThai":"Đang hoạt động","capNhatToi":"@c1315","tabs":{"tienTrinh":[{"chuong":"@c1315","loai":"nhắc tới","importance":"normal","giaiDoan":"Xét tư cách chọn linh địa","text":"Ngọc Khuyết Các tiếp nhận tài vật, phân tầng người xin động phủ theo tu vi và xét tư cách lựa chọn linh địa.","anchor":"tầng một này chỉ thích hợp cho Hắc Thiết vệ thôi, tiền bối phải đi lên tầng hai mới được"}]},"nguon":["@c1315"]},{"id":"hac-thiet-ve","name":"Hắc Thiết vệ","cn":"","type":"ve-binh","typeLabel":"Lực lượng vệ binh","diaBan":"Thiên Uyên Thành","nhanVatChinh":["Hắc Thiết Vệ cầm Dị Linh Bàn","Đại hán hung ác","Trung niên nữ tu"],"blurb":"Một cấp lực lượng vệ binh tại Thiên Uyên Thành. Thành viên Hắc Thiết vệ được bố trí xin linh địa tại tầng một Ngọc Khuyết Các. (+) Lực lượng giáp sĩ phối hợp với Thanh Minh vệ canh giữ cửa thạch tháp. [CAN-SOAT-GOP]","detail":"Hắc Thiết vệ là nhóm được xác định phù hợp với quy trình lựa chọn linh địa ở tầng một Ngọc Khuyết Các.","trangThai":"Đang tuần tra vùng biên","capNhatToi":"@c1315","tabs":{"tienTrinh":[{"chuong":"@c1315","loai":"nhắc tới","importance":"bridge","giaiDoan":"Phân tầng chọn linh địa","text":"Hắc Thiết vệ được bố trí lựa chọn linh địa tại tầng một Ngọc Khuyết Các.","anchor":"tầng một này chỉ thích hợp cho Hắc Thiết vệ thôi"},{"chuong":"@c1347","loai":"nhắc tới","importance":"normal","giaiDoan":"Phát hiện dị tộc","text":"Một đội mười Hắc Thiết Vệ đi qua Phù Lê Chiểu Trạch và phát hiện dấu hiệu dị tộc bằng Dị Linh Bàn.","anchor":"Có mười tên tu sĩ vận chiến giáp đen âm u","trangThaiMoc":"Đang cảnh giới"}]},"nguon":["@c1315","@c1347","@c1762"],"thanhVien":[{"ten":"Hắc Thiết Vệ cầm Dị Linh Bàn","chucVu":"Thành viên trinh sát","tuChuong":"@c1347","trangThai":"Đang hoạt động"},{"ten":"Đại hán hung ác","chucVu":"Thành viên tuần tra","tuChuong":"@c1347","trangThai":"Đang hoạt động"},{"ten":"Trung niên nữ tu","chucVu":"Thành viên tuần tra","tuChuong":"@c1347","trangThai":"Đang hoạt động"},{"ten":"Nhóm Hắc Thiết Vệ canh cửa thạch tháp","chucVu":"Giáp sĩ canh cửa","tuChuong":"@c1762","trangThai":"Đang phục vụ"}],"aliases":["Hắc vệ"]},{"id":"thien-uyen-thanh","name":"Thiên Uyên Thành","cn":"","type":"thanh-tri","typeLabel":"Thành trì kiêm thế lực quản lý","diaBan":"Thiên Uyên Thành và các vùng linh địa thuộc quyền quản lý","nhanVatChinh":["Tiêu sư thúc","Hàn Lập"],"blurb":"Thế lực giao nhiệm vụ nguy hiểm cho các phi thăng tu sĩ và dùng dược bình bị cấm chế để ràng buộc người chấp hành. (+) Thế lực quản lý việc tuyển chọn và phân phối linh địa cho tu sĩ tại Thiên Uyên Thành. [CAN-SOAT-GOP] (+) Thành trì lớn có Trưởng lão hội điều hành và hệ thống truyền tống đường dài. [CAN-SOAT-GOP]","detail":"Thiên Uyên Thành miễn cống nạp trong lần đầu chọn động phủ cho tu sĩ mới phi thăng. Mỗi người chỉ có một cơ hội tranh đoạt linh địa trong năm trăm năm, khiến việc thất bại đồng nghĩa phải chờ hết thời hạn mới được chọn lại.","quyMo":"Quản lý nhiều vùng linh địa và động phủ quanh thành","quanHe":"Tổ chức việc tuyển chọn linh địa cho các tu sĩ","trangThai":"Đang hoạt động","capNhatToi":"@c1316","tabs":{"tienTrinh":[{"chuong":"@c1316","loai":"nhắc tới","importance":"normal","giaiDoan":"Tổ chức tuyển chọn linh địa","text":"Thiên Uyên Thành tổ chức phân phối linh địa, miễn cống nạp lần đầu cho tu sĩ mới phi thăng và áp dụng thời hạn năm trăm năm cho mỗi cơ hội tranh đoạt.","anchor":"mỗi người chỉ có một lần cơ hội tranh đoạt linh địa"}]},"nguon":["@c1316","@c1369","@c1767","@c1994"],"thanhVien":[{"ten":"Hàn Lập","chucVu":"Người chấp hành nhiệm vụ","tuChuong":"@c1369","trangThai":"đang thực hiện nhiệm vụ"}]},{"id":"gioi-phi-thang-tu-si-trong-thien-uyen-thanh","name":"Giới phi thăng tu sĩ trong Thiên Uyên Thành","cn":"","type":"nhom-tu-si","typeLabel":"Nhóm tu sĩ","diaBan":"Thiên Uyên Thành","nhanVatChinh":["Hàn Lập"],"blurb":"Cộng đồng tu sĩ phi thăng sinh sống trong Thiên Uyên Thành, có xu hướng bảo vệ người cùng xuất thân.","detail":"Việc sát hại một phi thăng tu sĩ như Hàn Lập có thể khiến những người lớn tuổi trong cộng đồng này can thiệp và gây ra phong ba.","dacDiem":"Có xu hướng bảo vệ lẫn nhau.","quanHe":"Có thể đối đầu những kẻ sát hại thành viên cùng xuất thân.","trangThai":"Đang hoạt động","tabs":{"tienTrinh":[{"chuong":"@c1317","loai":"nhắc tới","importance":"bridge","giaiDoan":"Đang hoạt động","text":"Kim huynh cảnh báo rằng giới phi thăng tu sĩ trong thành có xu hướng bảo vệ lẫn nhau.","anchor":"Nhưng là trong thành phi thăng tu sĩ có chút bảo vệ nhau","trangThaiMoc":"Đang hoạt động"}]},"capNhatToi":"@c1317","nguon":["@c1317"]},{"id":"giam-sat-thien-ve","name":"Giám Sát Thiên Vệ","cn":"","type":"tổ chức chấp pháp","typeLabel":"Lực lượng giám sát","diaBan":"Thiên Uyên Thành","nhanVatChinh":[],"blurb":"Lực lượng có thành viên giám sát và can thiệp vào cuộc giao đấu giữa Hàn Lập với Hán tử họ Ông.","detail":"Một thành viên Giám Sát Thiên Vệ đã ra tay can thiệp, ngăn Hán tử họ Ông bị Hàn Lập dùng kiếm giết chết trong trận đấu trước đó.","quanHe":"Can thiệp vào các cuộc giao đấu thuộc phạm vi giám sát.","trangThai":"Đang hoạt động","tabs":{"tienTrinh":[{"chuong":"@c1322","loai":"nhắc tới","importance":"normal","giaiDoan":"Can thiệp giao đấu","text":"Giám Sát Thiên Vệ được xác nhận đã can thiệp và cứu Hán tử họ Ông khỏi đòn kiếm của Hàn Lập.","anchor":"nếu không nhờ Giám Sát Thiên Vệ ra tay tương trợ"}]},"capNhatToi":"@c1322","nguon":["@c1322"]},{"id":"cac-di-toc-linh-gioi","name":"Các Dị tộc Linh Giới","cn":"","type":"chung-toc","typeLabel":"Các chủng tộc","diaBan":"Nhiều khu vực và cấm địa tại Linh Giới","nhanVatChinh":[],"blurb":"Các chủng tộc khác tại Linh Giới sở hữu những Hỗn Độn Vạn Linh Bảng đặt trong cấm địa. Tin Huyền Thiên Trảm Linh Kiếm hiện thế khiến nhân vật tối cao của nhiều tộc bị kinh động.","detail":"Khi các bảng đồng thời hiển thị Huyền Thiên Trảm Linh Kiếm ở hạng ba, những tộc này âm thầm tăng cường canh phòng và củng cố phòng thủ.","quanHe":"Cùng phản ứng trước sự xuất hiện của Huyền Thiên Trảm Linh Kiếm.","trangThai":"Tăng cường phòng thủ","tabs":{"tienTrinh":[{"chuong":"@c1324","loai":"nhắc tới","importance":"normal","giaiDoan":"Ứng phó linh vật hiện thế","text":"Tin tức trên Hỗn Độn Vạn Linh Bảng làm kinh động nhân vật tối cao của nhiều Dị tộc và khiến họ bí mật tăng cường phòng thủ.","anchor":"khiến cho kinh động tới cả những nhân vật tối cao trong các Tộc.","trangThaiMoc":"Tăng cường canh phòng"}]},"capNhatToi":"@c1324","nguon":["@c1324"]},{"id":"tieu-doi-56-binh-doi","name":"Tiểu đội 56 Bính Đội","cn":"","type":"quan-su","typeLabel":"Đơn vị tuần tra","diaBan":"Thiên Uyên Thành","nhanVatChinh":["Hàn Lập","Trác Trùng","Đông Quách Phong","Mã đạo trưởng","Hứa tiên tử"],"blurb":"Tiểu đội 56 là một đơn vị thuộc khu vực Bính Đội tại Thiên Uyên Thành, đảm nhiệm việc chờ lệnh và tuần tra khu vực được phân công. Hàn Lập chính thức tiếp nhận chức đội trưởng của tiểu đội tại mốc @c1325.","detail":"Tiểu đội 56 trực thuộc Bính Đội ở Thiên Uyên Thành. Khi Hàn Lập tới đại điện chính thức nhận chức đội trưởng, Trác Trùng và Đông Quách Phong ra mắt, Mã đạo trưởng trở về sau đó, còn Hứa tiên tử vẫn đang ở bên ngoài; Hàn Lập đồng thời bắt đầu nghe báo cáo về nhân sự và nhiệm vụ tuần tra của đơn vị. @c1325","lanhDaoHienThoi":"Hàn Lập","tonChi":"Thực hiện nhiệm vụ tuần tra tại khu vực được phân công","capBac":"Tiểu đội thuộc Bính Đội","thanhVien":[{"ten":"Hàn Lập","chucVu":"Đội trưởng","tuChuong":"@c1325","trangThai":"Đang tại nhiệm"},{"ten":"Trác Trùng","chucVu":"Đội viên","tuChuong":"@c1325","trangThai":"Đang phục vụ"},{"ten":"Đông Quách Phong","chucVu":"Đội viên","tuChuong":"@c1325","trangThai":"Đang phục vụ"},{"ten":"Mã đạo trưởng","chucVu":"Đội viên","tuChuong":"@c1325","trangThai":"Đang phục vụ"},{"ten":"Hứa tiên tử","chucVu":"Đội viên","tuChuong":"@c1325","trangThai":"Đang phục vụ"}],"lanhDaoMoc":[{"ten":"Hàn Lập","tuChuong":"@c1325","denChuong":""}],"trangThai":"Đang hoạt động","capNhatToi":"@c1325","tabs":{"tienTrinh":[{"chuong":"@c1325","loai":"đổi lãnh đạo","importance":"major","giaiDoan":"Tiếp nhận đội trưởng mới","text":"Hàn Lập chính thức tới nhận chức đội trưởng tiểu đội 56 và bắt đầu nghe báo cáo về nhân sự cùng nhiệm vụ tuần tra.","anchor":"đích xác Hàn mỗ được bổ nhiệm làm Đội trưởng tiểu đội số 56","trangThaiMoc":"Hàn Lập trở thành đội trưởng"}]},"nguon":["@c1325"],"dacDiem":"Đơn vị tuần tra trực thuộc khu vực Bính Đội tại Thiên Uyên Thành.","congNang":["Chờ lệnh và thực hiện nhiệm vụ tuần tra tại khu vực được phân công. @c1325"]},{"id":"anh-toc","name":"Ảnh Tộc","cn":"","type":"di-toc","typeLabel":"Dị tộc","diaBan":"Phù Lê Chiểu Trạch","nhanVatChinh":[],"blurb":"Ảnh Tộc là một dị tộc nguy hiểm, từng được Thiên Nguyên Thánh Hoàng dự đoán sẽ tập kích đoàn tu sĩ phi thăng trên đường đến Dị Tộc. Thành viên của tộc này thường ẩn quanh Phù Lê Chiểu Trạch để giám thị Thiên Uyên Thành và từng đánh lén giết ba tu sĩ, trong đó có Hiên Nghiễm ở cảnh giới Hóa Thần trung kỳ.","detail":"Ảnh Tộc thường hoạt động quanh Phù Lê Chiểu Trạch, âm thầm giám thị Thiên Uyên Thành. Hai năm trước, người của tộc này đã đánh lén giết Hiên Nghiễm, đội trưởng đội số 12 có tu vi Hóa Thần trung kỳ, cùng hai đồng đạo của ông. Ảnh Tộc cũng từng được Thiên Nguyên Thánh Hoàng dự đoán sẽ tập kích đoàn tu sĩ phi thăng trên đường đến Dị Tộc.","quanHe":"Đối địch với lực lượng trấn thủ Thiên Uyên Thành.","trangThai":"Hoạt động quanh Phù Lê Chiểu Trạch","thanhVien":[{"ten":"Tử Ảnh","chucVu":"","tuChuong":"@c1357","trangThai":"bị bắt"}],"lanhDaoMoc":[],"tabs":{"tienTrinh":[{"chuong":"@c1326","loai":"nhắc tới","importance":"normal","giaiDoan":"Mối đe dọa tại Phù Lê","text":"Ảnh Tộc được nhắc lại với chiến tích đánh lén giết Hiên Nghiễm cùng hai đồng đạo hai năm trước.","anchor":"đội trưởng của đội số 12 Hiên Nghiễm tiền bối bị Ảnh Tộc nhân đánh lén đã vẫn lạc","trangThaiMoc":"Ẩn núp quanh Phù Lê Chiểu Trạch"}]},"capNhatToi":"@c1326","nguon":["@c1326","@c1357","@c1365","@c1369","@c1389"],"aliases":["Ảnh tộc"],"uyLuc":"Người của Ảnh Tộc từng đánh lén giết Hiên Nghiễm, một tu sĩ Hóa Thần trung kỳ, cùng hai đồng đạo của ông. @c1326","dacDiem":"Là dị tộc nguy hiểm, thường ẩn núp và tiến hành giám thị, đánh lén.","congNang":["Ẩn núp quanh Phù Lê Chiểu Trạch để giám thị Thiên Uyên Thành.","Có khả năng tổ chức đánh lén; từng giết Hiên Nghiễm cùng hai đồng đạo hai năm trước. @c1326"]},{"id":"doi-tuan-tra","name":"Đội tuần tra","cn":"","type":"doi-tuan-tra","typeLabel":"Đội tuần tra","diaBan":"Phù Lê Chiểu Trạch","nhanVatChinh":["Hàn Lập","Trác Trùng","Mã đạo trưởng","Doanh thiếu niên","Hứa tiên tử"],"blurb":"Đội ngũ tiến vào Phù Lê Chiểu Trạch để tuần tra và dò tìm dấu vết dị tộc.","detail":"Đội tuần tra hoạt động hơn hai mươi ngày trong Phù Lê Chiểu Trạch, liên tục dùng Dị Linh Bàn và thần niệm để dò xét. Tại một điểm nghỉ chân, cả đội bị cự thú ngụy trang thành bãi đá và Thúy trúc phục kích, sau đó tuân lệnh Hàn Lập đồng loạt tế bảo vật công kích.","quyMo":"Một đội tuần tra gồm Hàn Lập và nhiều đội viên","thanhVien":[{"ten":"Hàn Lập","chucVu":"Người chỉ huy","tuChuong":"@c1327","trangThai":"đang hoạt động"},{"ten":"Trác Trùng","chucVu":"Đội viên","tuChuong":"@c1327","trangThai":"đang hoạt động"},{"ten":"Mã đạo trưởng","chucVu":"Đội viên","tuChuong":"@c1327","trangThai":"đang hoạt động"},{"ten":"Doanh thiếu niên","chucVu":"Đội viên","tuChuong":"@c1327","trangThai":"đang hoạt động"},{"ten":"Hứa tiên tử","chucVu":"Đội viên","tuChuong":"@c1327","trangThai":"đang hoạt động"}],"trangThai":"Bị cự thú phục kích trong lúc tuần tra","capNhatToi":"@c1327","tabs":{"tienTrinh":[{"chuong":"@c1327","loai":"khai chiến","importance":"normal","giaiDoan":"Chạm trán cự thú","text":"Sau khi cự thú ngụy trang lộ diện, các thành viên đội tuần tra tuân lệnh Hàn Lập và đồng loạt tế bảo vật công kích.","anchor":"Đám Bích Nhãn đại hán rùng mình, lúc này nhao nhao tế xuất vô số bảo vật","trangThaiMoc":"Bị phục kích và bước vào giao chiến"}]},"nguon":["@c1327"]},{"id":"di-linh-duong","name":"Dị Linh Đường","cn":"","type":"to-chuc","typeLabel":"Cơ cấu xử lý dị linh","diaBan":"Tòa thành nơi nhóm Hàn Lập trở về","nhanVatChinh":[],"blurb":"Nơi tiếp nhận và xử lý các dị thú bị bắt giữ.","detail":"Hàn Lập ra lệnh đưa cự thú trong suốt về thành rồi giao cho Dị Linh Đường xử lý.","trangThai":"Đang hoạt động","capNhatToi":"@c1328","nguon":["@c1328"]},{"id":"man-thu-nhan","name":"Man thú nhân","cn":"","type":"di-toc","typeLabel":"Dị tộc","diaBan":"","nhanVatChinh":["Lục sắc quái nhân"],"blurb":"Một dị tộc có khả năng thi triển thần thông nhân thú hợp nhất với cự thú.","detail":"Thành viên Man thú nhân có thể nhập vào cự thú và hóa thành cự nhân hắc lân. Khả năng này khiến nhóm của Trác Trùng phải tìm cách ngăn cản ngay khi nhận ra thân phận đối phương.","dacDiem":"Có thần thông hợp nhất thành viên với cự thú.","thanhVien":[{"ten":"Lục sắc quái nhân","chucVu":"Thành viên","tuChuong":"@c1328","trangThai":"tu-vong"}],"trangThai":"Còn tồn tại","capNhatToi":"@c1328","nguon":["@c1328"]},{"id":"hoi-sinh-duong","name":"Hồi Sinh Đường","cn":"","aliases":[],"type":"thuong-hoi","typeLabel":"Dược điếm","diaBan":"Phường thị Linh Giới","nhanVatChinh":["Hàn Lập"],"blurb":"Một đại dược điếm tại phường thị Linh Giới, có khả năng thu mua linh thảo lâu năm với số lượng lớn.","detail":"Hồi Sinh Đường mua lại nhiều gốc linh thảo bảy tám nghìn năm do Hàn Lập cải trang mang tới và thanh toán cho hắn một lượng lớn linh thạch.","quyMo":"Đại dược điếm","quanHe":"Có giao dịch mua linh thảo với Hàn Lập","trangThai":"Đang hoạt động","thanhVien":[],"capNhatToi":"@c1330","tabs":{"tienTrinh":[{"chuong":"@c1330","loai":"nhắc tới","importance":"normal","giaiDoan":"Thu mua linh thảo lâu năm","text":"Hồi Sinh Đường mua nhiều gốc linh thảo bảy tám nghìn năm từ Hàn Lập và trả một lượng lớn linh thạch.","anchor":"Hồi Sinh Đường không chút do dự xuất ra nhiều linh thạch mua lại các linh thảo này."}]},"nguon":["@c1330"]},{"id":"kim-ve","name":"Kim Vệ","cn":"","aliases":[],"type":"quan-su","typeLabel":"Lực lượng hộ vệ","diaBan":"Thái Huyền Điện","nhanVatChinh":[],"blurb":"Lực lượng hộ vệ cấp cao tham gia duy trì trật tự giao dịch giữa Nhân Tộc và Yêu Tộc tại Thái Huyền Điện. (+) Một lực lượng từng dẫn Liễu lão giả tham gia nhiệm vụ càn quét dị tộc vô danh. [CAN-SOAT-GOP]","detail":"Bốn Kim Vệ có tu vi Luyện Hư phối hợp với mười Thanh Minh Vệ để ngăn xung đột trong đại điện. Tổng lực lượng hộ vệ được chia đều cho hai tộc.","capBac":"Luyện Hư kỳ","quyMo":"Bốn người tại Thái Huyền Điện","soCaoThu":"Bốn Kim Vệ cấp Luyện Hư","quanHe":"Phối hợp với Thanh Minh Vệ duy trì trật tự","trangThai":"Đang làm nhiệm vụ","thanhVien":[],"capNhatToi":"@c1330","tabs":{"tienTrinh":[{"chuong":"@c1330","loai":"nhắc tới","importance":"normal","giaiDoan":"Bảo vệ khu giao dịch","text":"Bốn Kim Vệ cấp Luyện Hư phối hợp với Thanh Minh Vệ duy trì trật tự trong Thái Huyền Điện.","anchor":"Ngoài ra lại còn có bốn Kim Vệ cấp Luyện Hư Kỳ và mười Thanh Minh Vệ duy trì trật tự."}]},"nguon":["@c1330","@c1389"]},{"id":"tieu-doi-27","name":"Tiểu đội 27","cn":"","type":"don-vi","typeLabel":"Tiểu đội","diaBan":"Thiên Uyên Thành","nhanVatChinh":["Hoàng Bảo","Trung niên lùn mặt rỗ"],"blurb":"Đơn vị do Hoàng Bảo lãnh đội. Hoàng Bảo cùng đồ đệ tới địa bàn tiểu đội 56 để ép Hứa tiên tử thực hiện hôn ước.","detail":"Hoàng Bảo tự xác nhận mình là lãnh đội tiểu đội 27. Trong chương này, hành động của hắn và đồ đệ dẫn tới cuộc kiểm chứng Lục Ba Nhận trước mặt Hàn Lập.","lanhDaoHienThoi":"Hoàng Bảo","thanhVien":[{"ten":"Hoàng Bảo","chucVu":"Lãnh đội","tuChuong":"@c1333","trangThai":"đang tại vị"},{"ten":"Trung niên lùn mặt rỗ","chucVu":"Thành viên","tuChuong":"@c1333","trangThai":"đang hoạt động"}],"capNhatToi":"@c1333","nguon":["@c1333"]},{"id":"luu-sa-coc","name":"Lưu Sa Cốc","cn":"","type":"tong-mon","typeLabel":"Tông môn","diaBan":"","nhanVatChinh":["Hoàng Bảo","Trung niên lùn mặt rỗ"],"blurb":"Tiểu tông môn là nơi xuất thân của thầy trò Hoàng Bảo.","detail":"Lưu Sa Cốc không phải đại tông môn có truyền thừa thượng cổ. Hoàng Bảo giữ địa vị trưởng lão tối cao tại đây.","quyMo":"Tiểu tông môn","lanhDaoHienThoi":"Hoàng Bảo giữ chức trưởng lão tối cao","caoThuManhNhat":"Hoàng Bảo","trangThai":"Đang tồn tại","thanhVien":[{"ten":"Hoàng Bảo","chucVu":"Trưởng lão tối cao","tuChuong":"@c1334","trangThai":"đang thuộc"},{"ten":"Trung niên lùn mặt rỗ","chucVu":"Môn nhân","tuChuong":"@c1334","trangThai":"đang thuộc"}],"capNhatToi":"@c1334","tabs":{"tienTrinh":[{"chuong":"@c1334","loai":"xuất hiện","importance":"normal","giaiDoan":"Được xác nhận lai lịch","text":"Lưu Sa Cốc được xác nhận là tiểu tông môn của thầy trò Hoàng Bảo, trong đó Hoàng Bảo giữ chức trưởng lão tối cao.","anchor":"Thầy trò Hoàng Bảo đều xuất thân từ một cái tiểu tông môn gọi là Lưu Sa Cốc","trangThaiMoc":"Đang tồn tại"}]},"nguon":["@c1334"]},{"id":"hoi-dau-gia-thai-huyen-dien","name":"Hội đấu giá Thái Huyền Điện","cn":"","type":"to-chuc","typeLabel":"Tổ chức đấu giá","diaBan":"Thái Huyền Điện, Thiên Uyên Thành","nhanVatChinh":["Xích đại sư","Thủ vệ Thái Huyền Điện","Hơn mười cung trang nữ tu"],"blurb":"Tổ chức kỳ đấu giá dành cho tu sĩ từ Hóa Thần trở lên tại Thái Huyền Điện.","detail":"Hội đấu giá sử dụng ngọc bội che giấu dung mạo, pháp trận truyền tống và gần một nghìn Phi Thiên Thạch Ốc để bảo vệ danh tính người tham gia. Kỳ đấu giá này bất ngờ công bố ba vật phẩm áp trục và cho phép người mua dùng vật phẩm quý hiếm thay thế linh thạch sau khi được định giá.","tonChi":"Tổ chức giao dịch vật phẩm cấp cao và bảo vệ danh tính người tham gia","lanhDaoHienThoi":"Xích đại sư phụ trách chủ trì kỳ đấu giá @c1335","quyMo":"Gần một nghìn vị trí biệt lập, với mấy trăm tu sĩ nhanh chóng tham dự @c1335","thanhVien":[{"ten":"Xích đại sư","chucVu":"Người giám định kiêm chủ trì","tuChuong":"@c1335","trangThai":"Đang đảm nhiệm"},{"ten":"Thủ vệ Thái Huyền Điện","chucVu":"Kiểm tra và hướng dẫn khách","tuChuong":"@c1335","trangThai":"Đang làm nhiệm vụ"},{"ten":"Hơn mười cung trang nữ tu","chucVu":"Phục vụ và trình vật phẩm","tuChuong":"@c1335","trangThai":"Đang làm nhiệm vụ"}],"tabs":{"tienTrinh":[{"chuong":"@c1335","loai":"nhắc tới","importance":"normal","giaiDoan":"Tổ chức kỳ đấu giá đặc biệt","text":"Hội đấu giá tập hợp đông đảo tu sĩ cấp cao, công bố ba vật phẩm áp trục và cho phép dùng vật phẩm quý hiếm thay linh thạch.","anchor":"Đương nhiên lần đấu giá ba kiện này có chút vội vàng nên đặc biệt có thể cho phép đấu giá nhân thay thế linh thạch bằng các vật phẩm quý hiếm khác."}]},"capNhatToi":"@c1335","nguon":["@c1335"]},{"id":"lung-gia","name":"Lũng gia","cn":"","type":"chan-linh-the-gia","typeLabel":"Chân Linh thế gia","diaBan":"Thao túng hoạt động đấu giá tại Tam Cảnh","nhanVatChinh":["Tử bào thanh niên có nốt ruồi đỏ"],"blurb":"Lũng gia là Chân Linh thế gia lưu truyền từ Thượng Cổ, mang Chân Long Huyết Mạch và được xưng là đệ nhất trong hàng ngũ Chân Linh thế gia. Gia tộc từng bố trí một cuộc đấu giá làm bẫy, dùng nhiều vật quý để tìm người kế thừa Thiên Phượng Huyết Mạch.","detail":"Lũng gia có truyền thừa từ Thượng Cổ, trong tộc có lão tổ đạt Hợp Thể hậu kỳ đại thành, cùng các thành viên như Lũng Đông và những tu sĩ song tu từng tham gia tranh đoạt Huyết Tinh Ma Ha Kiếm. Để dụ người kế thừa Thiên Phượng Huyết Mạch xuất hiện, gia tộc đưa nhiều bảo vật làm mồi tại cuộc đấu giá, gồm Âm Dương Hóa Cực Quyết, Mặc Kỳ Lân Lân Phiến và Bình Hải Qua. Sau khi một nữ tu bí ẩn đoạt được công pháp, công tử Lũng gia suy đoán người mang Thiên Phượng Huyết Mạch đã lộ diện. @c1339","nguonGoc":"Chân Linh thế gia lưu truyền từ Thượng Cổ","lanhDaoHienThoi":"Chưa rõ","caoThuManhNhat":"Chưa rõ","tranPhai":"Chân Long Huyết Mạch","trangThai":"Đang dò tìm người kế thừa Thiên Phượng Huyết Mạch","thanhVien":[{"ten":"Tử bào thanh niên có nốt ruồi đỏ","chucVu":"Công tử","tuChuong":"@c1339","trangThai":"đang hoạt động"},{"ten":"Lũng Đông","chucVu":"Thiếu chủ","tuChuong":"@c1382","trangThai":"đang hoạt động"},{"ten":"Lũng gia song tu","chucVu":"Tu sĩ","tuChuong":"@c1382","trangThai":"đang hoạt động"},{"ten":"Lũng gia lão tổ","chucVu":"Lão tổ","tuChuong":"@c1801","trangThai":"đương nhiệm"},{"ten":"Lũng gia gia chủ","chucVu":"Gia chủ đương nhiệm","tuChuong":"@c1804","trangThai":"đang tại tầng chín Nghênh Tiên cung"},{"ten":"Nam tử trung niên Lũng gia","chucVu":"Đệ tử","tuChuong":"@c1804","trangThai":"đang hoạt động"},{"ten":"Nữ tử trẻ tuổi Lũng gia","chucVu":"Đệ tử","tuChuong":"@c1804","trangThai":"đang hoạt động"},{"ten":"Huy trưởng lão","chucVu":"Trưởng lão","tuChuong":"@c1833","trangThai":"đang hoạt động"},{"ten":"Nam tử áo bào đen","chucVu":"Thái Thượng Trưởng Lão","tuChuong":"@c1876","trangThai":"Đang hoạt động"}],"capNhatToi":"@c1339","tabs":{"tienTrinh":[{"chuong":"@c1339","loai":"nhắc tới","importance":"normal","giaiDoan":"Bố trí bẫy đấu giá","text":"Lũng gia dùng nhiều vật quý trong tộc làm mồi đấu giá để dụ người kế thừa Thiên Phượng Huyết Mạch xuất hiện.","anchor":"Lũng gia chúng ta thì thao túng đấu giá cả Tam Cảnh"}]},"nguon":["@c1339","@c1382","@c1801","@c1804","@c1833","@c1876"],"uyLuc":"Lão tổ Lũng gia đã đạt Hợp Thể hậu kỳ đại thành, khiến gia tộc được xưng là đệ nhất trong hàng ngũ Chân Linh thế gia.","dacDiem":"Chân Linh thế gia truyền thừa từ Thượng Cổ, mang Chân Long Huyết Mạch.","congNang":["Có thể huy động nhiều vật quý trong tộc làm mồi đấu giá nhằm dụ và xác định người kế thừa Thiên Phượng Huyết Mạch. @c1339"]},{"id":"coc-gia","name":"Cốc gia","cn":"","type":"chan-linh-the-gia","typeLabel":"Chân Linh thế gia","diaBan":"Các mỏ cực phẩm linh thạch trong Nhân tộc","nhanVatChinh":[],"blurb":"Chân Linh thế gia âm thầm kiểm soát nhiều mỏ cực phẩm linh thạch và ít xuất hiện bên ngoài. Gia tộc bị nghi có liên quan đến nữ tu mua Âm Dương Hóa Cực Quyết, nhưng nhận định này chưa được xác nhận. (+) Cốc gia giữ được vị trí cuối trong Ngũ đại Chân Linh thế gia nhờ Hàn Lập đại diện ứng chiến. [CAN-SOAT-GOP]","detail":"Cốc gia cùng Diệp gia được công tử Lũng gia nêu như hai khả năng về nguồn gốc của người có thể mang Thiên Phượng Huyết Mạch.","trangThai":"Hoạt động kín đáo","capNhatToi":"@c1339","tabs":{"tienTrinh":[{"chuong":"@c1339","loai":"nhắc tới","importance":"bridge","giaiDoan":"Bị nghi liên quan nữ tu","text":"Cốc gia bị nghi là một trong hai gia tộc có thể liên quan đến nữ tu mua Âm Dương Hóa Cực Quyết.","anchor":"bọn họ lại âm thầm khống chế số lượng kinh người các mỏ quặng cực phẩm linh thạch trong Nhân Tộc."}]},"nguon":["@c1339","@c1831","@c1832","@c1833"],"thanhVien":[{"ten":"Hiểu Phong tiên tử","chucVu":"Gia chủ","tuChuong":"@c1832","trangThai":"đương nhiệm"},{"ten":"Tiêu trưởng lão","chucVu":"Trưởng lão","tuChuong":"@c1832","trangThai":"đang hoạt động"}]},{"id":"nhuan-gia","name":"Nhuận gia","cn":"","type":"chan-linh-gia-toc","typeLabel":"Chân Linh gia tộc","diaBan":"Không rõ","nhanVatChinh":["Thiên Diệu Linh Hoàng"],"blurb":"Gia tộc có huyết mạch không thuộc loại Chân Linh cường đại nhưng nổi trội trong Nhân tộc về đào tạo linh thảo. Lũng gia nghi người đưa ra Vạn Năm Linh Thảo có thể liên quan tới gia tộc này.","detail":"Khả năng người mua Chân Linh Lân Phiến thuộc Nhuận gia khiến công tử Lũng gia quyết định không tùy tiện truy xét.","trangThai":"Không rõ","capNhatToi":"@c1339","nguon":["@c1339"]},{"id":"thiem-gia","name":"Thiểm gia","cn":"","type":"gia-toc","typeLabel":"Gia tộc","diaBan":"Không rõ","nhanVatChinh":[],"blurb":"Một gia tộc được công tử Lũng gia nêu như khả năng khác về lai lịch của người mua Chân Linh Lân Phiến. Chương chưa xác nhận Hàn Lập có liên quan tới gia tộc này.","detail":"Thông tin về Thiểm gia trong chương chỉ giới hạn ở khả năng người mua Chân Linh Lân Phiến có thể mang thân phận liên quan đến gia tộc.","trangThai":"Không rõ","capNhatToi":"@c1339","nguon":["@c1339"]},{"id":"chan-linh-the-gia","name":"Chân Linh thế gia","cn":"","type":"nhom-the-luc","typeLabel":"Nhóm thế lực","diaBan":"Nhân tộc và Thiên Uyên Thành","nhanVatChinh":[],"blurb":"Nhóm các gia tộc truyền thừa Chân Linh Huyết Mạch từ Thượng Cổ. Nhiều đệ tử của các gia tộc này đang che giấu tung tích trong Thiên Uyên Thành. (+) Thế gia sở hữu những tử đệ mang Chân Huyết dung nhập sâu vào thân thể. [CAN-SOAT-GOP] (+) Nhóm các gia tộc tham dự Chân linh đại điển ba nghìn năm một lần. Thứ hạng tại đại điển quyết định số đệ tử được tiến vào linh động cùng nhiều lợi ích khác. [CAN-SOAT-GOP]","detail":"Sự hiện diện bí mật của các đệ tử Chân Linh thế gia khiến Lũng gia bố trí cuộc đấu giá làm bẫy để dò tìm người kế thừa Thiên Phượng Huyết Mạch.","nguonGoc":"Các gia tộc truyền thừa Chân Linh Huyết Mạch từ Thượng Cổ","trangThai":"Nhiều đệ tử đang ẩn giấu trong Thiên Uyên Thành","capNhatToi":"@c1339","tabs":{"tienTrinh":[{"chuong":"@c1339","loai":"nhắc tới","importance":"normal","giaiDoan":"Đệ tử bí mật tụ tập","text":"Nhiều đệ tử Chân Linh thế gia được tiết lộ đang che giấu tung tích trong Thiên Uyên Thành.","anchor":"Thì ra các Chân Linh thế gia đệ tử đều che giấu tung tích ẩn trốn trong Thiên Uyên Thành"}]},"nguon":["@c1339","@c1355","@c1822"],"thanhVien":[{"ten":"Diệp Dĩnh","chucVu":"Đệ tử","tuChuong":"@c1355","trangThai":"Đang hoạt động"}]},{"id":"chap-phap-doi-thien-uyen-thanh","name":"Chấp Pháp Đội Thiên Uyên Thành","cn":"","type":"co-quan-chap-phap","typeLabel":"Cơ cấu chấp pháp","diaBan":"Thiên Uyên Thành","nhanVatChinh":[],"blurb":"Cơ cấu phụ trách điều tra và xử lý các hành vi vi phạm luật lệ tại Thiên Uyên Thành.","detail":"Chấp Pháp Đội có thể điều tra việc tự tiện xâm nhập linh địa và công kích đồng liêu. Hàn Lập viện dẫn quyền điều tra, sưu hồn và xử phạt của cơ cấu này để khiến hai kẻ canh giữ dè chừng.","tonChi":"Duy trì luật lệ và xử lý hành vi xâm phạm quyền lợi của tu sĩ trong thành.","quanHe":"Trực thuộc hệ thống quản lý của Thiên Uyên Thành.","trangThai":"Hoạt động","capNhatToi":"@c1343","tabs":{"tienTrinh":[{"chuong":"@c1343","loai":"nhắc tới","importance":"bridge","giaiDoan":"Được viện dẫn","text":"Hàn Lập dùng quyền điều tra và xử phạt của Chấp Pháp Đội để kiềm chế những người xâm nhập linh địa.","anchor":"ắt hẳn sẽ làm cho Chấp Pháp Đội cảm thấy hứng thú","trangThaiMoc":"Hoạt động"}]},"nguon":["@c1343"]},{"id":"hu-dong-toc","name":"Hư Động Tộc","cn":"","type":"di-toc","typeLabel":"Dị tộc","diaBan":"Không rõ","nhanVatChinh":[],"blurb":"Một dị tộc hiếm khi xuất hiện gần tuyến tuần tra của Thiên Uyên Thành. Tộc nhân của họ từng gây thiệt hại nặng cho Tiểu đội số bốn.","detail":"Nửa năm trước, Tiểu đội số bốn chạm trán Hư Động Tộc Nhân và mất hơn nửa quân số, trong đó có đội trưởng.","quanHe":"Đối địch với lực lượng tuần tra Thiên Uyên Thành","trangThai":"Có dấu hiệu hoạt động gần vùng biên","tabs":{"tienTrinh":[{"chuong":"@c1347","loai":"nhắc tới","importance":"normal","giaiDoan":"Gây tổn thất tuần tra","text":"Hư Động Tộc Nhân được nhắc là đối thủ đã khiến Tiểu đội số bốn mất hơn nửa quân số cùng đội trưởng.","anchor":"đã gặp phải Hư Động Tộc Nhân rất hiếm khi thấy qua","trangThaiMoc":"Xuất hiện gần tuyến tuần tra"}]},"capNhatToi":"@c1347","nguon":["@c1347"]},{"id":"dong-hu-toc","name":"Động Hư Tộc","cn":"","type":"dị tộc","typeLabel":"Dị tộc Linh Giới","diaBan":"Khu vực quanh Thiên Uyên Thành","nhanVatChinh":[],"blurb":"Một Dị Tộc có cao giai xuất hiện trong khu vực tuần tra quanh Thiên Uyên Thành.","detail":"Sự tồn tại của một cao giai Động Hư Tộc vừa được phát hiện trước khi Hàn Lập bắt Lục Ảnh. Việc này góp phần cho thấy hoạt động của nhiều Dị Tộc quanh Thiên Uyên Thành đang tăng lên bất thường.","trangThai":"Tăng cường hoạt động do thám","capNhatToi":"@c1349","tabs":{"tienTrinh":[{"chuong":"@c1349","loai":"nhắc tới","importance":"normal","giaiDoan":"Phát hiện cao giai","text":"Một cao giai Động Hư Tộc được phát hiện trong khu vực tuần tra quanh Thiên Uyên Thành.","anchor":"Vừa rồi mới phát hiện sự tồn tại của cao giai Động Hư Tộc","trangThaiMoc":"Cao giai xuất hiện tại khu tuần tra"}]},"nguon":["@c1349"]},{"id":"di-toc","name":"Dị Tộc","cn":"","type":"liên nhóm","typeLabel":"Nhóm các Dị Tộc","diaBan":"Khu vực quanh Thiên Uyên Thành","nhanVatChinh":[],"blurb":"Cách gọi chung các Dị Tộc đang gia tăng hoạt động do thám quanh Thiên Uyên Thành.","detail":"Thám tử của nhiều Dị Tộc xuất hiện với tần suất và cấp bậc khác thường tại Phù Lê Chiểu Trạch cùng Táng Cốt Sa Mạc. Tiểu đội Hàn Lập vì thế bắt đầu nghi ngờ một cuộc tiến công Thiên Uyên Thành đang được chuẩn bị.","quanHe":"Đối địch với lực lượng phòng thủ Thiên Uyên Thành","trangThai":"Bị nghi đang chuẩn bị tiến công Thiên Uyên Thành","capNhatToi":"@c1349","tabs":{"tienTrinh":[{"chuong":"@c1349","loai":"khai chiến","importance":"normal","giaiDoan":"Nảy sinh nghi vấn công thành","text":"Hoạt động do thám gia tăng khiến tiểu đội Hàn Lập nghi ngờ Dị Tộc đang chuẩn bị tiến công Thiên Uyên Thành.","anchor":"Chẵng lẽ Dị Tộc có chủ ý muốn tấn công Thiên Uyên Thành?","trangThaiMoc":"Bị nghi chuẩn bị công thành"}]},"nguon":["@c1349"]},{"id":"luan-cong-cac","name":"Luận Công Các","cn":"","type":"co-quan","typeLabel":"Cơ cấu xét công trạng","diaBan":"Thiên Uyên Thành","nhanVatChinh":["Hàn Lập","Văn tiền bối"],"blurb":"Cơ cấu tiếp nhận và xét duyệt công trạng tại Thiên Uyên Thành.","detail":"Văn tiền bối chuyển hồ sơ chiến công bắt sống Lục Ảnh của Hàn Lập tới Luận Công Các. Công trạng này được dùng để xét tư cách vào Thiên Nghiễm Điện nghe giảng.","tonChi":"Tiếp nhận và xét duyệt công trạng","thanhVien":[],"trangThai":"Đang hoạt động","capNhatToi":"@c1350","tabs":{"tienTrinh":[{"chuong":"@c1350","loai":"nhắc tới","importance":"normal","giaiDoan":"Tiếp nhận chiến công","text":"Luận Công Các tiếp nhận hồ sơ công trạng bắt sống Lục Ảnh để xét tư cách nghe giảng cho Hàn Lập.","anchor":"sau đó truyền tới Luận Công Các, với công trạng này chắc ngươi có thể vào nghe giảng đạo được","trangThaiMoc":"Tiếp nhận hồ sơ của Hàn Lập"}]},"nguon":["@c1350"]},{"id":"phi-thang-tu-si-thien-uyen-thanh","name":"Phi thăng tu sĩ tại Thiên Uyên Thành","cn":"","type":"nhom-tu-si","typeLabel":"Nhóm tu sĩ","diaBan":"Thiên Uyên Thành và địa điểm tụ hội bí mật ngoài thành","nhanVatChinh":["Hàn Lập","Văn tu sĩ","Triệu Vô Quy","Phạm đạo hữu","Lão giả mặt đỏ như say rượu"],"blurb":"Nhóm phi thăng tu sĩ sinh hoạt tại Thiên Uyên Thành và tổ chức các kỳ tụ hội để trao đổi tâm đắc tu luyện cùng tin tình báo.","detail":"Khoảng mười lăm đến mười sáu tu sĩ Hóa Thần tham dự kỳ tụ hội ngoài thành. Do Phạm đạo hữu bận việc, Văn tu sĩ và Triệu Vô Quy thay mặt chủ trì, giải đáp khúc mắc tu luyện và thu nhận tình báo trong bối cảnh dị tộc có khả năng công thành.","quyMo":"Khoảng mười lăm đến mười sáu tu sĩ Hóa Thần tham dự kỳ tụ hội này.","thanhVien":[{"ten":"Hàn Lập","chucVu":"Người tham dự","tuChuong":"@c1351","trangThai":"Đang tham dự"},{"ten":"Văn tu sĩ","chucVu":"Người thay mặt chủ trì","tuChuong":"@c1351","trangThai":"Đang hoạt động"},{"ten":"Triệu Vô Quy","chucVu":"Người thay mặt chủ trì","tuChuong":"@c1351","trangThai":"Đang hoạt động"},{"ten":"Phạm đạo hữu","chucVu":"Người vốn chủ trì","tuChuong":"@c1351","trangThai":"Vắng mặt trong kỳ tụ hội"},{"ten":"Lão giả mặt đỏ như say rượu","chucVu":"Người tham dự","tuChuong":"@c1351","trangThai":"Đang tham dự"}],"tabs":{"tienTrinh":[{"chuong":"@c1351","loai":"nhắc tới","importance":"normal","giaiDoan":"Tổ chức tụ hội trước nguy cơ công thành","text":"Các phi thăng tu sĩ tụ họp để trao đổi tâm đắc tu luyện, giải đáp khúc mắc và cung cấp tình báo trong tình hình đặc thù.","anchor":"Đáng lẽ là Phạm đạo hữu chủ trì phi thăng tu sĩ tụ hội này","trangThaiMoc":"Đang tổ chức tụ hội"}]},"capNhatToi":"@c1351","nguon":["@c1351"]},{"id":"truong-lao-hoi-thien-uyen-thanh","name":"Trưởng Lão Hội Thiên Uyên Thành","cn":"","type":"hoi-dong","typeLabel":"Cơ cấu trưởng lão","diaBan":"Thiên Uyên Thành","nhanVatChinh":["Lôi La Chân Nhân","Triệu Vô Quy","Văn tu sĩ"],"blurb":"Tổ chức trưởng lão của Thiên Uyên thành, trong đó có các thành viên xuất thân tu sĩ phi thăng. Sau khi Lôi La chân nhân vẫn lạc, Kim Việt Thiền Sư tìm cách mời Hàn Lập gia nhập để tăng tiếng nói cho nhóm này. (+) Cơ cấu công bố và quản lý các nhiệm vụ đặc biệt tại Thiên Uyên Thành. [CAN-SOAT-GOP]","detail":"Trưởng Lão Hội công bố một loạt nhiệm vụ nguy hiểm liên quan đến Dị Tộc. Các nhiệm vụ chỉ dành cho tu sĩ Hóa Thần và treo mức công huân lớn, nhưng ít người dám tiếp nhận vì nguy cơ tử vong cao.","capBac":"Trưởng Lão Hội","tranPhai":"Các nhiệm vụ đặc biệt liên quan Dị Tộc","trangThai":"Đang hoạt động","capNhatToi":"@c1353","tabs":{"tienTrinh":[{"chuong":"@c1353","loai":"khai chiến","importance":"normal","giaiDoan":"Công bố nhiệm vụ đặc biệt","text":"Trưởng Lão Hội công bố các nhiệm vụ nguy hiểm liên quan đến Dị Tộc, giới hạn người tham gia ở cấp Hóa Thần và treo công huân lớn.","anchor":"Trưởng Lão Hội cũng tuyên bố các nhiệm vụ mang tính nguy hiểm dị thường nhưng sẽ nhận được công huân rất lớn."}]},"nguon":["@c1353","@c1764","@c1838","@c1990"],"aliases":["Thiên Uyên thành Trưởng lão hội"],"thanhVien":[{"ten":"Kim Việt Thiền Sư","chucVu":"Trưởng lão","tuChuong":"@c1764","trangThai":"đương nhiệm"},{"ten":"Thích trưởng lão","chucVu":"Trưởng lão","tuChuong":"@c1764","trangThai":"đương nhiệm"},{"ten":"Lôi La chân nhân","chucVu":"Trưởng lão","tuChuong":"@c1764","trangThai":"đã vẫn lạc"},{"ten":"Cốc huynh","chucVu":"Trưởng lão","tuChuong":"@c1990","trangThai":"đương nhiệm"}]}]};
